export default JSON.parse('{"work":{"id":"wu-zi","schoolId":"military","title":"吳子","genreStrategy":"parallel","sourceNote":"版本來源自通行本及校勘附記。","chapterIds":["wu-zi_ch-1","wu-zi_ch-2","wu-zi_ch-3","wu-zi_ch-4","wu-zi_ch-5","wu-zi_ch-6"],"totalChars":5906},"chapters":[{"id":"wu-zi_ch-1","workId":"wu-zi","order":1,"title":"圖國","difficulty":4,"estimatedMinutes":10,"passageIds":["wu-zi_ch-1_p-1","wu-zi_ch-1_p-2","wu-zi_ch-1_p-3","wu-zi_ch-1_p-4","wu-zi_ch-1_p-5","wu-zi_ch-1_p-6","wu-zi_ch-1_p-7","wu-zi_ch-1_p-8"],"tags":[]},{"id":"wu-zi_ch-2","workId":"wu-zi","order":2,"title":"料敵","difficulty":4,"estimatedMinutes":10,"passageIds":["wu-zi_ch-2_p-1","wu-zi_ch-2_p-2","wu-zi_ch-2_p-3","wu-zi_ch-2_p-4"],"tags":[]},{"id":"wu-zi_ch-3","workId":"wu-zi","order":3,"title":"治兵","difficulty":4,"estimatedMinutes":10,"passageIds":["wu-zi_ch-3_p-1","wu-zi_ch-3_p-2","wu-zi_ch-3_p-3","wu-zi_ch-3_p-4","wu-zi_ch-3_p-5","wu-zi_ch-3_p-6","wu-zi_ch-3_p-7","wu-zi_ch-3_p-8"],"tags":[]},{"id":"wu-zi_ch-4","workId":"wu-zi","order":4,"title":"論將","difficulty":4,"estimatedMinutes":10,"passageIds":["wu-zi_ch-4_p-1","wu-zi_ch-4_p-2","wu-zi_ch-4_p-3","wu-zi_ch-4_p-4","wu-zi_ch-4_p-5"],"tags":[]},{"id":"wu-zi_ch-5","workId":"wu-zi","order":5,"title":"應變","difficulty":4,"estimatedMinutes":10,"passageIds":["wu-zi_ch-5_p-1","wu-zi_ch-5_p-2","wu-zi_ch-5_p-3","wu-zi_ch-5_p-4","wu-zi_ch-5_p-5","wu-zi_ch-5_p-6","wu-zi_ch-5_p-7","wu-zi_ch-5_p-8","wu-zi_ch-5_p-9","wu-zi_ch-5_p-10","wu-zi_ch-5_p-11"],"tags":[]},{"id":"wu-zi_ch-6","workId":"wu-zi","order":6,"title":"勵士","difficulty":4,"estimatedMinutes":10,"passageIds":["wu-zi_ch-6_p-1","wu-zi_ch-6_p-2","wu-zi_ch-6_p-3","wu-zi_ch-6_p-4","wu-zi_ch-6_p-5","wu-zi_ch-6_p-6"],"tags":[]}],"passages":[{"id":"wu-zi_ch-1_p-1","chapterId":"wu-zi_ch-1","order":1,"canonicalText":"吳起儒服以兵機見魏文侯。文侯曰：「寡人不好軍旅之事。」起曰：「臣以見占隱，以往察來，主君何言與心違？今君四時使斬離皮革，掩以朱漆，畫以丹青，爍以犀象。冬日衣之則不溫，夏日衣之則不涼。為長戟二丈四尺，短戟一丈二尺。革車奄戶，縵輪籠轂，觀之於目則不麗，乘之以田則不輕，不識主君安用此也？若以備進戰退守，而不求能用者，譬猶伏雞之搏狸，乳犬之犯虎，雖有鬥心，隨之死矣。昔承桑氏之君，修德廢武，以滅其國。有扈氏之君，恃眾好勇，以喪其社稷。明主鑒茲，必內修文德，外治武備。故當敵而不進，無逮於義矣；僵屍而哀之，無逮於仁矣。」於是文侯身自布席，夫人捧觴，醮吳起於廟，立為大將，守西河。與諸侯大戰七十六，全勝六十四，餘則鈞解。闢土四面，拓地千里，皆起之功也。","sentenceIds":["wu-zi_ch-1_p-1_s-1","wu-zi_ch-1_p-1_s-2","wu-zi_ch-1_p-1_s-3","wu-zi_ch-1_p-1_s-4","wu-zi_ch-1_p-1_s-5","wu-zi_ch-1_p-1_s-6","wu-zi_ch-1_p-1_s-7","wu-zi_ch-1_p-1_s-8","wu-zi_ch-1_p-1_s-9","wu-zi_ch-1_p-1_s-10","wu-zi_ch-1_p-1_s-11","wu-zi_ch-1_p-1_s-12","wu-zi_ch-1_p-1_s-13","wu-zi_ch-1_p-1_s-14","wu-zi_ch-1_p-1_s-15","wu-zi_ch-1_p-1_s-16"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"吳起身穿儒服，以精通兵法機謀面見魏文侯。文侯說：「我不喜歡軍事打仗之事。」吳起說：「臣能從顯露的現象推測隱微的事物，從過去的經歷察知未來的發展，主君說的話為什麼與心裡想的不一樣呢？如今您一年四季讓人裁切皮革製造鎧甲，塗上朱漆，繪飾彩畫，鑲嵌犀角象牙。冬天穿它並不溫暖，夏天穿它並不涼爽。又製造長達二丈四尺的長戟，和一丈二尺的短戟。用皮革包裹戰車的車戶，蒙上車輪、籠罩轂心，論觀賞並不美觀，駕乘去打獵也不輕便，臣實在不明白主君要這些東西有何用處？如果這是用來準備進攻戰鬥或後退防守，卻不尋求懂得出兵作戰的人才，就好比抱窩的母雞去搏擊野貓，哺乳的母狗去侵犯猛虎，雖然有鬥志，接著就只有死亡了。從前承桑氏的國君，專修文德而廢棄武備，結果國家遭到滅亡；有扈氏的國君，仗著人口眾多、逞勇好鬥，結果喪失了社稷。明智的君主引此為鑑，必定在內修明文德，在外整備武備。因此面對敵人卻不敢進擊，就稱不上義；等到戰死積屍纔去哀悼，就稱不上仁了。」於是魏文侯親自為他鋪設席位，夫人親捧酒杯，在宗廟中為吳起舉行祭酒授任之禮，立他為大將，鎮守西河地區。吳起後來與各諸侯國大戰七十六次，全勝六十四次，其餘幾次也是不相上下。魏國向四面開疆拓土千里，都是吳起的功勞。","analysis":"【主題與背景】\\\\n本段記載吳起以儒生裝束面見魏文侯，直指魏文侯表面聲稱不喜軍旅，實則暗中擴充武備但欠缺戰略人才的矛盾，進而論述文德與武備兼修的重要性。\\\\n\\\\n【詞義與名物】\\\\n「以見佔隱」：透過表面現象推斷隱微本質。「承桑氏」、「有扈氏」：古代因偏廢文德或武備而滅亡的歷史反面教材。「醮」：古代於宗廟中授任大將的隆重禮儀。\\\\n\\\\n【兵家戰略】\\\\n吳起指出「內修文德，外治武備」是國家安全的雙軌基礎。光有精良裝備而無懂兵善戰之將，如「伏雞搏狸」必然自取滅亡；兵家思想在此呈現出政治文德與軍事武備不可偏廢的辯證關係。"}},{"id":"wu-zi_ch-1_p-2","chapterId":"wu-zi_ch-1","order":2,"canonicalText":"吳子曰：「昔之圖國家者，必先教百姓而親萬民。有四不和：不和於國，不可以出軍；不和於軍，不可以出陳；不和於陳，不可以進戰；不和於戰，不可以決勝。是以有道之主，將用其民，先和而造大事。不敢信其私謀，必告於祖廟，啟於元龜，參之天時，吉乃後舉。民知君之愛其命，惜其死，若此之至，而與之臨難，則士以盡死為榮，退生為辱矣。」","sentenceIds":["wu-zi_ch-1_p-2_s-1","wu-zi_ch-1_p-2_s-2","wu-zi_ch-1_p-2_s-3","wu-zi_ch-1_p-2_s-4","wu-zi_ch-1_p-2_s-5","wu-zi_ch-1_p-2_s-6","wu-zi_ch-1_p-2_s-7","wu-zi_ch-1_p-2_s-8","wu-zi_ch-1_p-2_s-9"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"吳子說：「從前謀劃國家大業的人，必定先教化百姓、親近萬民。作戰有四種『不和』：國內人心不和，不可出動軍隊；軍隊內部不和，不可擺開陣勢；陣勢之間不和，不可推進作戰；戰鬥協調不和，不可決求勝負。因此有道的君主想要動用百姓時，必定先做到和諧纔去開創大事。他們不敢過分自信於私人的謀劃，必定先稟告祖廟，開卜大龜，參考天時運勢，獲得吉兆之後才採取行動。百姓知道君主如此關愛他們的生命、痛惜他們的死亡，達到了這種至誠的地步，此時與百姓共同面對危難，士兵就會以戰死沙場為榮，以苟活後退為辱了。」","analysis":"【主題與背景】\\\\n本段闡述「以和為本」與「愛民惜死」的政治軍事哲學，強調軍事勝利建立在國內團結、軍心一致與民心歸順的基礎上。\\\\n\\\\n【詞義與名物】\\\\n「四不和」：國不和、軍不和、陳不和、戰不和，由巨觀政局至微觀戰術層層遞進。「元龜」：古代用於國家重大決策卜筮的大龜。\\\\n\\\\n【兵家戰略】\\\\n吳起提出「先和而造大事」，強調軍隊的戰鬥力來源於民心。君主若能展現對士兵生命的極致愛護，士兵便能產生同仇敵儾、視死如歸的強大凝聚力。"}},{"id":"wu-zi_ch-1_p-3","chapterId":"wu-zi_ch-1","order":3,"canonicalText":"吳子曰：「夫道者，所以反本復始。義者，所以行事立功。謀者，所以違害就利。要者，所以保業守成。若行不合道，舉不合義，而處大居貴，患必及之。是以聖人綏之以道，理之以義，動之以禮，撫之以仁。此四德者，修之則興，廢之則衰。故成湯討桀而夏民喜悅，周武伐紂而殷人不非。舉順天人，故能然矣。」","sentenceIds":["wu-zi_ch-1_p-3_s-1","wu-zi_ch-1_p-3_s-2","wu-zi_ch-1_p-3_s-3","wu-zi_ch-1_p-3_s-4","wu-zi_ch-1_p-3_s-5","wu-zi_ch-1_p-3_s-6","wu-zi_ch-1_p-3_s-7","wu-zi_ch-1_p-3_s-8","wu-zi_ch-1_p-3_s-9","wu-zi_ch-1_p-3_s-10"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"吳子說：「所謂『道』，是用來返璞歸真、順應根本的；『義』，是用來推行事務、建立功業的；『謀』，是用來避開危害、趨向有利的；『要』，是用來鞏固家業、守住成效的。如果行為不合於道，舉動不合於義，卻身處高位尊貴之處，禍患必定會降臨到身上。因此聖人用『道』安撫萬民，用『義』治理事務，用『禮』規範行動，用『仁』關懷體恤。這四種美德，修明它國家就會興盛，廢棄它國家就會衰亡。所以商湯討伐夏桀而夏國百姓歡喜，周武王討伐商紂而商朝人民不加非議，正是因為他們的舉措順應了天理與人心啊。」","analysis":"【主題與背景】\\\\n本段提出道、義、謀、要四項立國根本，並結合道、義、禮、仁四德，論證正義之師順應天人的合法性。\\\\n\\\\n【詞義與名物】\\\\n「反本復始」：回到天理人情的根本。「成湯討桀」、「周武伐紂」：古代順應天命人心的革命正義範例。\\\\n\\\\n【兵家戰略】\\\\n吳起將兵家戰略納入儒道政治倫理架構中，認為「舉順天人」是戰爭獲得政治合法性與戰術勝利的終極保證。"}},{"id":"wu-zi_ch-1_p-4","chapterId":"wu-zi_ch-1","order":4,"canonicalText":"吳子曰：「凡制國治軍，必教之以禮，勵之以義，使有恥也。夫人有恥，在大足以戰，在小足以守矣。然戰勝易，守勝難。故曰：天下戰國，五勝者禍，四勝者弊，三勝者霸，二勝者王，一勝者帝。是以數勝得天下者稀，以亡者眾。」","sentenceIds":["wu-zi_ch-1_p-4_s-1","wu-zi_ch-1_p-4_s-2","wu-zi_ch-1_p-4_s-3","wu-zi_ch-1_p-4_s-4","wu-zi_ch-1_p-4_s-5","wu-zi_ch-1_p-4_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"吳子說：「凡是治理國家與統率軍隊，必定要用『禮』來教化，用『義』來鼓勵，使士兵產生羞恥心。人只要有了羞恥心，兵力多時足可以用於進攻戰鬥，兵力少時足可以用於堅守防禦。然而戰勝敵人容易，鞏固勝利成果卻困難。所以說：天下從事戰爭的國家，靠武力獲得五次勝利的會招致禍害，四次勝利的會疲弊衰落，三次勝利的可以成就霸業，兩次勝利的可以成就王業，一次勝利就能平定天下的則可成就帝業。因此靠多次打勝仗而取得天下的極為稀少，因而導致滅亡的反而極多。」","analysis":"【主題與背景】\\\\n本段深刻剖析了戰爭頻率與國家興衰的關係，提出著名的「五勝者禍，一勝者帝」戰略警示。\\\\n\\\\n【詞義與名物】\\\\n「有恥」：具有榮辱觀與道德恥辱感。「守勝」：戰勝之後如何鞏固戰果、養息國力。\\\\n\\\\n【兵家戰略】\\\\n吳起警惕過度用兵與盲目追求軍事勝利的副作用。頻繁戰爭會窮兵黷武、耗盡國力（五勝者禍），唯有結合強大政治整合力、少戰而大勝者才能實現長治久安。"}},{"id":"wu-zi_ch-1_p-5","chapterId":"wu-zi_ch-1","order":5,"canonicalText":"吳子曰：「凡兵之所起者有五：一曰爭名，二曰爭利，三曰積德惡，四曰內亂，五曰因饑。其名又有五：一曰義兵，二曰彊兵，三曰剛兵，四曰暴兵，五曰逆兵。禁暴救亂曰義，恃眾以伐曰彊，因怒興師曰剛，棄禮貪利曰暴，國亂人疲舉事動眾曰逆。五者之數，各有其道，義必以禮服，彊必以謙服，剛必以辭服，暴必以詐服，逆必以權服。」","sentenceIds":["wu-zi_ch-1_p-5_s-1","wu-zi_ch-1_p-5_s-2","wu-zi_ch-1_p-5_s-3","wu-zi_ch-1_p-5_s-4","wu-zi_ch-1_p-5_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"吳子說：「凡是戰爭爆發的原因有五種：一是爭奪名聲，二是爭奪利益，三是積怨深重，四是國家內亂，五是遇到饑荒。戰爭的性質名稱也有五種：一是義兵，二是強兵，三是剛兵，四是暴兵，五是逆兵。禁止暴虐、救援動亂稱為『義兵』；仗著兵多去討伐稱為『強兵』；因一時發怒而興師稱為『剛兵』；背棄禮義、貪圖利益稱為『暴兵』；國家混亂、人民疲憊卻盲目動員軍隊稱為『逆兵』。應對這五種性質的軍隊，各有不同的原則：對付義兵必須用禮義折服，對付強兵必須用謙遜應對，對付剛兵必須用外交言語化解，對付暴兵必須用奇謀詐術剋制，對付逆兵則必須用權謀機變制勝。」","analysis":"【主題與背景】\\\\n本段對戰爭的起因與性質進行系統分類，並方針性地提出針對不同類型敵軍的剋制戰略。\\\\n\\\\n【詞義與名物】\\\\n「五兵」：義兵、強兵、剛兵、暴兵、逆兵。「五服」：禮服、謙服、辭服、詐服、權服。\\\\n\\\\n【兵家戰略】\\\\n吳起強調「因敵施策」，區分戰爭的道德正當性與力量對比，主張對於正義或強大的對手不可以硬碰硬，對於暴逆之敵則需靈活採取權謀與奇計。"}},{"id":"wu-zi_ch-1_p-6","chapterId":"wu-zi_ch-1","order":6,"canonicalText":"武侯問曰：「願聞治兵、料人、固國之道。」起對曰：「古之明王，必謹君臣之禮，飾上下之儀，安集吏民，順俗而教，簡募良材，以備不虞。昔齊桓募士五萬，以霸諸侯。晉文召為前行四萬，以獲其志。秦繆置陷陳三萬，以服鄰敵。故強國之君，必料其民。民有膽勇氣力者，聚為一卒。樂以進戰效力、以顯其忠勇者，聚為一卒。能踰高超遠、輕足善走者，聚為一卒。王臣失位而欲見功於上者，聚為一卒。棄城去守、欲除其醜者，聚為一卒。此五者，軍之練銳也。有此三千人，內出可以決圍，外入可以屠城矣。」","sentenceIds":["wu-zi_ch-1_p-6_s-1","wu-zi_ch-1_p-6_s-2","wu-zi_ch-1_p-6_s-3","wu-zi_ch-1_p-6_s-4","wu-zi_ch-1_p-6_s-5","wu-zi_ch-1_p-6_s-6","wu-zi_ch-1_p-6_s-7","wu-zi_ch-1_p-6_s-8","wu-zi_ch-1_p-6_s-9","wu-zi_ch-1_p-6_s-10","wu-zi_ch-1_p-6_s-11","wu-zi_ch-1_p-6_s-12","wu-zi_ch-1_p-6_s-13","wu-zi_ch-1_p-6_s-14"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"魏武侯問道：「我想聽聽治理軍隊、考量人才、鞏固國家的道理。」吳起回答說：「古代明智的君王，必定嚴謹遵守君臣禮節，整飭上下儀制，安撫聚集官吏百姓，順應風俗進行教化，選拔招募優秀人才，以防備意料之外的變故。從前齊桓公招募精兵五萬，因而稱霸諸候；晉文公召集四萬精銳作為前鋒，因而實現志向；秦穆公設置陷陣勇士三萬，因而征服鄰敵。所以強國的君主，必定審察考量自己的百姓。百姓中膽勇過人、體力強健的，編聚為一隊；樂於向前戰鬥效力、展現忠勇的，編聚為一隊；能夠攀高跳遠、腳步輕快善於奔跑的，編聚為一隊；王臣失去官位而急於向上立功的，編聚為一隊；曾棄城失守而想要洗刷羞恥的，編聚為一隊。這五類人，是軍隊中最精銳的骨幹。擁有這樣的精銳三千人，由內突圍可以突破重圍，由外進攻可以攻克敵城。」","analysis":"【主題與背景】\\\\n本段論述精兵政策與兵員分類編組的戰術思想，主張根據士兵的心理特徵與體能專長進行針對性編排。\\\\n\\\\n【詞義與名物】\\\\n「料人」：審察、評估民力與個體特徵。「練銳」：經過嚴格篩選與針對性組合的精銳特別行動部隊。\\\\n\\\\n【兵家戰略】\\\\n吳起開創了軍隊「特種選拔與專業化編組」的先河。將具有同類心理動機（如洗刷羞恥、求功心切）或身體特長者集中編隊，能發揮遠超普通部隊的爆發力與突擊效能。"}},{"id":"wu-zi_ch-1_p-7","chapterId":"wu-zi_ch-1","order":7,"canonicalText":"武侯問曰：「願聞陳必定、守必固、戰必勝之道。」起對曰：「立見且可，豈直聞乎！君能使賢者居上，不肖者處下，則陳已定矣。民安其田宅，親其有司，則守已固矣。百姓皆是吾君而非鄰國，則戰已勝矣。」","sentenceIds":["wu-zi_ch-1_p-7_s-1","wu-zi_ch-1_p-7_s-2","wu-zi_ch-1_p-7_s-3","wu-zi_ch-1_p-7_s-4","wu-zi_ch-1_p-7_s-5","wu-zi_ch-1_p-7_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"魏武侯問道：「我想聽聽陣勢必定穩定、防守必定堅固、作戰必定勝利的道理。」吳起回答說：「這立刻就能看到成效，豈止是聽聽而已呢！主君如果能讓有德有才的人身居高位，讓無德無才的人處於下位，那麼陣勢就已經穩定了；百姓安居於他們的田宅，親近他們的官吏，那麼防守就已經堅固了；百姓都認同贊許我們自己的君主，而指責非難鄰國，那麼戰鬥就已經勝利了。」","analysis":"【主題與背景】\\\\n本段以極具說服力的對答，將陣勢、防守、作戰這三項軍事指標，直接歸結為用人、民生與政治認同。\\\\n\\\\n【詞義與名物】\\\\n「陳必定、守必固、戰必勝」：傳統軍事作戰的三大核心目標。「有司」：管理基層事務的官員。\\\\n\\\\n【兵家戰略】\\\\n吳起展現了「兵政合一」的最高智慧：軍事上的勝負在戰場之外就已決定。任人唯賢則指揮層穩定，基層安居則防守穩固，人心歸附則戰無不勝。"}},{"id":"wu-zi_ch-1_p-8","chapterId":"wu-zi_ch-1","order":8,"canonicalText":"武侯嘗謀事，群臣莫能及，罷朝而有喜色。起進曰：「昔楚莊王嘗謀事，群臣莫能及，退朝而有憂色。申公問曰：『君有憂色，何也？』曰：『寡人聞之，世不絕聖，國不乏賢，能得其師者王，得其友者霸。今寡人不才，而群臣莫及者，楚國其殆矣。』此楚莊王之所憂，而君說之，臣竊懼矣。」於是武侯有慚色。","sentenceIds":["wu-zi_ch-1_p-8_s-1","wu-zi_ch-1_p-8_s-2","wu-zi_ch-1_p-8_s-3","wu-zi_ch-1_p-8_s-4","wu-zi_ch-1_p-8_s-5","wu-zi_ch-1_p-8_s-6","wu-zi_ch-1_p-8_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"魏武侯曾經與群臣商議國事，群臣的見識沒有一個能比得上他，退朝後武侯面露喜色。吳起走上前說：「從前楚莊王曾經與群臣商議國事，群臣的見識沒有一個能比得上他，退朝後楚莊王卻面帶憂色。申公問道：『君王面帶憂色，是為什麼呢？』楚莊王說：『我聽說世上不會斷絕聖人，國家不會缺乏賢才，能找到可以作為自己老師的人就能成就王業，能找到可以作為自己朋友的人就能成就霸業。如今我天資不才，而群臣卻還比不上我，楚國恐怕要危險了！』這正是楚莊王所擔憂的事，而主君您卻為此感到高興，臣私下感到非常害怕。」魏武侯聽了之後，臉上露出了慚愧的神色。","analysis":"【主題與背景】\\\\n本段記載吳起借楚莊王求賢若渴、謙遜自省的歷史典故，直言勸諫魏武侯切勿因群臣平庸而盲目自滿。\\\\n\\\\n【詞義與名物】\\\\n「得其師者王，得其友者霸」：能尊賢為師者可興王道，能結交賢能為友者可成霸業。\\\\n\\\\n【兵家戰略】\\\\n吳起強調「將道與君道」在政治領導力上的謙虛品格。君主若因群臣不如己而沾沾自喜，將導致智囊匱乏、決策孤立，是國家最深層的戰略危機。"}},{"id":"wu-zi_ch-2_p-1","chapterId":"wu-zi_ch-2","order":1,"canonicalText":"武侯謂吳起曰：「今秦脅吾西，楚帶吾南，趙衝吾北，齊臨吾東，燕絕吾後，韓據吾前。六國兵四守，勢甚不便，憂此奈何？」起對曰：「夫安國家之道，先戒為寶。今君已戒，禍其遠矣。臣請論六國之俗：夫齊陳重而不堅，秦陳散而自鬭，楚陳整而不久，燕陳守而不走，三晉陳治而不用。夫齊性剛，其國富，君臣驕奢而簡於細民，其政寬而祿不均，一陳兩心，前重後輕，故重而不堅。擊此之道，必三分之，獵其左右，脅而從之，其陳可壞。秦性強，其地險，其政嚴，其賞罰信，其人不讓，皆有鬭心，故散而自戰。擊此之道，必先示之以利而引去之，士貪於得而離其將，乘乖獵散，設伏投機，其將可取。楚性弱，其地廣，其政騷，其民疲，故整而不久。擊此之道，襲亂其屯，先奪其氣。輕進速退，弊而勞之，勿與戰爭，其軍可敗。燕性愨，其民慎，好勇義，寡詐謀，故守而不走。擊此之道，觸而迫之，陵而遠之，馳而後之，則上疑而下懼，謹我車騎必避之路，其將可虜。三晉者，中國也，其性和，其政平，其民疲於戰，習於兵，輕其將，薄其祿，士無死志，故治而不用。擊此之道，阻陳而壓之，眾來則拒之，去則追之，以倦其師。此其勢也。然則一軍之中，必有虎賁之士；力輕扛鼎，足輕戎馬，搴旗斬將，必有能者。若此之等，選而別之，愛而貴之，是謂軍命。其有工用五兵、材力健疾、志在吞敵者，必加其爵列，可以決勝。厚其父母妻子，勸賞畏罰，此堅陳之士，可與持久。能審料此，可以擊倍。」武侯曰：「善。」","sentenceIds":["wu-zi_ch-2_p-1_s-1","wu-zi_ch-2_p-1_s-2","wu-zi_ch-2_p-1_s-3","wu-zi_ch-2_p-1_s-4","wu-zi_ch-2_p-1_s-5","wu-zi_ch-2_p-1_s-6","wu-zi_ch-2_p-1_s-7","wu-zi_ch-2_p-1_s-8","wu-zi_ch-2_p-1_s-9","wu-zi_ch-2_p-1_s-10","wu-zi_ch-2_p-1_s-11","wu-zi_ch-2_p-1_s-12","wu-zi_ch-2_p-1_s-13","wu-zi_ch-2_p-1_s-14","wu-zi_ch-2_p-1_s-15","wu-zi_ch-2_p-1_s-16","wu-zi_ch-2_p-1_s-17","wu-zi_ch-2_p-1_s-18","wu-zi_ch-2_p-1_s-19","wu-zi_ch-2_p-1_s-20","wu-zi_ch-2_p-1_s-21","wu-zi_ch-2_p-1_s-22","wu-zi_ch-2_p-1_s-23","wu-zi_ch-2_p-1_s-24","wu-zi_ch-2_p-1_s-25"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"魏武侯對吳起說：「如今秦國在西面威脅我們，楚國在南面包圍我們，趙國在北面直衝我們，齊國在東面逼近我們，燕國在後面切斷退路，韓國在前面扼守要衝。六國大軍環伺四方，形勢非常不利，我為此憂慮該怎麼辦？」吳起回答說：「安邦定國之道，以預先警惕最為寶貴。如今主君已經有了戒備，禍害自然就遠離了。請允許臣論述六國的風俗特徵：齊國的軍陣看似笨重卻不堅固；秦國的軍陣分散而各自為戰；楚國的軍陣整齊卻不能持久；燕國的軍陣固守卻不敢主動出擊；三晉（韓、趙、魏）的軍陣治理整齊卻缺乏戰鬥意志。齊人性格剛強，國家富有，君臣驕奢而輕視平民，政治寬鬆而奉祿不均，同一個軍陣卻君臣異心，前重後輕，所以笨重而不堅固。攻擊齊軍的方法，必須將軍隊一分為三，騷擾襲擊其左右兩翼，脅迫跟隨，其軍陣即可破壞。秦人性格強悍，地形險要，政治嚴酷，賞罰誠信，人們互不謙讓而富有鬥志，所以分散各自為戰。攻擊秦軍的方法，必須先展示利益將其引開，士兵貪圖利益就會脫離將領，乘其脫節分散、設下伏兵抓住時機，其將領即可擒獲。楚人性格懦弱，土地廣袤，政令紛擾，百姓疲憊，所以陣勢整齊卻不能持久。攻擊楚軍的方法，是襲擊騷擾其營屯，先摧毀其士氣，輕快進擊快速撤退，使其疲憊不堪，不與其正面決戰，其軍隊即可擊敗。燕人性格誠實，民風謹慎，喜好勇義，缺少詐謀，所以堅守而不退跑。攻擊燕軍的方法，是衝擊逼迫，凌駕遠繞，快速奔襲其後方，使其上層猜疑、下層恐懼，嚴密防範我方車騎留出敵必避之路，其將領即可俘獲。三晉位於中原，民風溫和，政治平穩，人民因頻繁戰爭而疲憊，雖熟悉軍事，卻輕視將領、奉祿薄少，士兵沒有必死意志，所以軍陣整齊卻沒有戰鬥力。攻擊三晉軍隊的方法，是阻擋其軍陣並施加壓力，敵大軍前來則拒守，退去則追擊，使其軍隊疲憊。這就是各國的形勢特點。然而在一支軍隊中，必定有勇猛如虎的勇士，力能扛鼎、足能追奔馬，能砍旗斬將者，必定有這種能人。像這樣的人，挑選出來另外編組，愛護並尊貴他們，這叫做軍隊的命脈。如果有精通五種兵器、體力健捷、志在吞滅敵人者，一定要提升他們的爵位，可以靠他們決勝。厚待他們的父母妻子，用賞賜鼓勵、用刑罰震懾，這是堅固軍陣的士卒，可以與敵人持久對抗。能夠審慎考量這些，就可以打敗倍數於己的敵人。」武侯說：「講得好！」","analysis":"【主題與背景】\\\\n本段是中國古代戰略地理與各國兵風民俗的經典剖析。吳起針對戰國初期魏國被秦、楚、趙、齊、燕、韓六國環伺的嚴峻局勢，逐一拆解六國軍隊的性格、陣勢特點與相應的戰術破法。\\\\n\\\\n【詞義與名物】\\\\n「重而不堅、散而自鬭、整而不久、守而不走、治而不用」：吳起對齊、秦、楚、燕、三晉軍事特徵的五大名評。「虎賁之士」：軍中極其勇猛精銳的特別突擊隊。\\\\n\\\\n【兵家戰略】\\\\n吳起展現了「知己知彼、因敵制勝」的頂級戰略戰術思維。不抽象論戰，而是將政治、風俗、性格、地形與戰術有機結合，強調根據對手的具體弱點採用分化、利誘、疲敵、心理威嚇等不同戰術。"}},{"id":"wu-zi_ch-2_p-2","chapterId":"wu-zi_ch-2","order":2,"canonicalText":"吳子曰：「凡料敵有不卜而與之戰者八：一曰疾風大寒，早興寤遷，刊木濟水，不憚艱難；二曰盛夏炎熱，晏興無間，行驅飢渴，務於取遠；三曰師既淹久，糧食無有，百姓怨怒，祅祥數起，上不能止；四曰軍資既竭，薪芻既寡，天多陰雨，欲掠無所；五曰徒眾不多，水地不利，人馬疾疫，四鄰不至；六曰道遠日暮，士眾勞懼，倦而未食，解甲而息；七曰將薄吏輕，士卒不固，三軍數驚，師徒無助；八曰陳而未定，舍而未畢，行阪涉險，半隱半出。諸如此者，擊之勿疑。有不占而避之者六：一曰土地廣大，人民富眾；二曰上愛其下，惠施流布；三曰賞信刑察，發必得時；四曰陳功居列，任賢使能；五曰師徒之眾，兵甲之精；六曰四鄰之助，大國之援。凡此不如敵人，避之勿疑。所謂見可而進，知難而退也。」","sentenceIds":["wu-zi_ch-2_p-2_s-1","wu-zi_ch-2_p-2_s-2","wu-zi_ch-2_p-2_s-3","wu-zi_ch-2_p-2_s-4","wu-zi_ch-2_p-2_s-5","wu-zi_ch-2_p-2_s-6","wu-zi_ch-2_p-2_s-7","wu-zi_ch-2_p-2_s-8","wu-zi_ch-2_p-2_s-9","wu-zi_ch-2_p-2_s-10","wu-zi_ch-2_p-2_s-11","wu-zi_ch-2_p-2_s-12","wu-zi_ch-2_p-2_s-13","wu-zi_ch-2_p-2_s-14","wu-zi_ch-2_p-2_s-15","wu-zi_ch-2_p-2_s-16","wu-zi_ch-2_p-2_s-17","wu-zi_ch-2_p-2_s-18"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"吳子說：「凡是考量敵人，有八種情況不必占卜就可以與之交戰：一是大風嚴寒，敵人早起拔營移屯，砍伐樹木渡水，不避艱難；二是盛夏炎熱，敵軍起得晚且無間隔休息，急行軍飢渴難耐，一心遠行；三是敵軍出征已久，糧食斷絕，百姓怨恨怒罵，凶兆頻起，上層無法制止；四是軍用物資耗盡，柴草匱乏，天多陰雨，想搶劫也無處搶；五是兵眾不多，水土不利，人馬染病，四鄰救援不到；六是道路遙遠日落西山，士眾疲憊恐懼，飢腸轆轆卻未吃飯，解開鎧甲休息；七是將領平庸官吏輕浮，士卒人心不固，三軍屢次驚恐，軍隊孤立無援；八是列陣未定，宿營未畢，行經山坡過險，隊伍半隱半現。凡屬此類情況，果斷攻擊無須猶豫。有六種情況不必占卜就必須避開敵人：一是土地廣大，人口富庶；二是上層愛護下屬，恩惠廣泛流佈；三是賞賜誠信刑罰明察，出兵必合時宜；四是論功行賞按功排列，任人唯賢；五是軍隊數量眾多，武器裝備精良；六是四鄰鼎力相助，有大國為後援。凡在這些方面不如敵人，果斷避開無須猶豫。這就是所謂的『見可而進，知難而退』。」","analysis":"【主題與背景】\\\\n本段系統總結了八種「可擊之敵」與六種「不可擊（應避）之敵」的具體指標，是戰場情報評估與決策選擇的經典法則。\\\\n\\\\n【詞義與名物】\\\\n「八可擊、六應避」：基於天時、地理、糧餉、士氣、將領、政治六個維度的軍事實力評估體系。\\\\n\\\\n【兵家戰略】\\\\n吳起強調理性決策，反對迷信占卜。當敵人處於疲憊、困頓、混亂、將庸、陣腳未穩時應果斷主動出擊；而當敵人政治清明、民心團結、軍備精良時則應避其鋒芒。"}},{"id":"wu-zi_ch-2_p-3","chapterId":"wu-zi_ch-2","order":3,"canonicalText":"武侯問曰：「吾欲觀敵之外以知其內，察其進以知其止，以定勝負，可得聞乎？」起對曰：「敵人之來，蕩蕩無慮，旌旗煩亂，人馬數顧，一可擊十，必使無措。諸侯大會，君臣未和，溝壘未成，禁令未施，三軍匈匈，欲前不能，欲去不敢，以半擊倍，百戰不殆。」","sentenceIds":["wu-zi_ch-2_p-3_s-1","wu-zi_ch-2_p-3_s-2","wu-zi_ch-2_p-3_s-3","wu-zi_ch-2_p-3_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"魏武侯問道：「我想通過觀察敵人的外表來瞭解其內部，觀察敵人的推進來推知其企圖，從而預定勝負，可以聽聽具體戰法嗎？」吳起回答說：「敵人前來時，若陣勢鬆散毫無防備，旗幟雜亂無章，人馬頻繁回顧，我方可以一擊十，必使敵人措手不及。若諸侯聯軍會集，君臣人心不和，深溝高壘尚未築成，軍紀禁令尚未施行，三軍騷動喧嘩，想前進不能、想後退不敢，此時我方以一半兵力攻擊敵倍數之眾，亦可百戰不殆。」","analysis":"【主題與背景】\\\\n本段論述如何通過敵軍的外在表象（隊形、旗幟、精神狀態）判斷其內部虛實與戰鬥力。\\\\n\\\\n【詞義與名物】\\\\n「觀外知內」：通過外在微觀行為推知內部組織狀態與士氣。「三軍匈匈」：軍隊內部騷亂不安。\\\\n\\\\n【兵家戰略】\\\\n吳起指出隊形混亂、旗幟雜亂、人馬顧盼是敵軍缺乏訓練與心懷恐懼的明確指標；聯軍內部矛盾與營壘未成則是致命弱點，掌握此時機可以少勝多。"}},{"id":"wu-zi_ch-2_p-4","chapterId":"wu-zi_ch-2","order":4,"canonicalText":"武侯問敵必可擊之道。起對曰：「用兵必須審敵虛實而趨其危。敵人遠來新至、行列未定可擊，既食未設備可擊，奔走可擊，勤勞可擊，未得地利可擊，失時不從可擊，旌旗亂動可擊，涉長道後行未息可擊，涉水半渡可擊，險道狹路可擊，陳數移動可擊，將離士卒可擊，心怖可擊。凡若此者，選銳衝之，分兵繼之，急擊勿疑。」","sentenceIds":["wu-zi_ch-2_p-4_s-1","wu-zi_ch-2_p-4_s-2","wu-zi_ch-2_p-4_s-3","wu-zi_ch-2_p-4_s-4","wu-zi_ch-2_p-4_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"魏武侯詢問敵人必定可以攻擊的具體時機。吳起回答說：「用兵作戰必須審察敵人的虛實而奔向敵人的危難困境。敵人遠道而來初次到達、行列未定時可以攻擊；剛剛吃飯尚未設置防備時可以攻擊；奔波逃跑時可以攻擊；勞累疲憊時可以攻擊；未佔據有利地形時可以攻擊；錯失時機不合天時可以攻擊；旌旗混亂晃動時可以攻擊；經過長途跋涉隊尾未獲休息時可以攻擊；渡水渡到一半時可以攻擊；行經險道狹路時可以攻擊；軍陣頻繁移動時可以攻擊；將領脫離士卒時可以攻擊；內心恐懼時可以攻擊。凡遇到這類情況，挑選精銳部隊發起衝鋒，分出兵力後續跟進，迅速果斷發起攻擊，絕不猶豫。」","analysis":"【主題與背景】\\\\n本段詳盡列舉了十三種戰場上敵軍顯露致命漏洞的「必擊」時機與應對戰術。\\\\n\\\\n【詞義與名物】\\\\n「審虛實而趨其危」：審察敵人之虛實，專挑敵人最脆弱危險之處猛擊。「涉水半渡」：兵家傳統的「半渡而擊」經典時機。\\\\n\\\\n【兵家戰略】\\\\n吳起提倡極致的機動性與決斷力。只要敵軍處於狀態不穩、防禦鬆懈、地形不利或心理恐懼的瞬間，即應以精銳為先鋒迅速突擊，使敵人無法組織有效反擊。"}},{"id":"wu-zi_ch-3_p-1","chapterId":"wu-zi_ch-3","order":1,"canonicalText":"武侯問曰：「進兵之道何先？」起對曰：「先明四輕、二重、一信。」曰：「何謂也？」對曰：「使地輕馬，馬輕車，車輕人，人輕戰。明知陰陽，則地輕馬。芻秣以時，則馬輕車。膏鐧有餘，則車輕人。鋒銳甲堅，則人輕戰。進有重賞，退有重刑。行之以信。令制遠，此勝之主也。」","sentenceIds":["wu-zi_ch-3_p-1_s-1","wu-zi_ch-3_p-1_s-2","wu-zi_ch-3_p-1_s-3","wu-zi_ch-3_p-1_s-4","wu-zi_ch-3_p-1_s-5","wu-zi_ch-3_p-1_s-6","wu-zi_ch-3_p-1_s-7","wu-zi_ch-3_p-1_s-8","wu-zi_ch-3_p-1_s-9","wu-zi_ch-3_p-1_s-10","wu-zi_ch-3_p-1_s-11","wu-zi_ch-3_p-1_s-12"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"魏武侯問道：「推進軍隊的途徑以什麼為優先？」吳起回答說：「首先要明確『四輕、二重、一信』。」武侯問：「這話是什麼意思呢？」回答說：「要做到地有利於馬（地輕馬），馬適於拉車（馬輕車），車便於載人（車輕人），人樂於作戰（人輕戰）。明白掌握陰陽氣候，地就能利於馬；按時餵養草料，馬就能適於拉車；車軸潤滑充沛，車就能便於載人；武器鋒利鎧甲堅固，人就能樂於作戰。前進有重賞，後退有重刑，貫徹實行貴在誠信。掌握好這些原則，就是戰勝敵人的主導因素。」","analysis":"【主題與背景】\\\\n本段提出著名的軍隊後勤裝備與士氣連鎖理論——「四輕二重一信」，將作戰準備拆解為人、車、馬、地、軍紀的系統工程。\\\\n\\\\n【詞義與名物】\\\\n「四輕」：地輕馬、馬輕車、車輕人、人輕戰。「二重一信」：進有重賞、退有重刑、行之以信。\\\\n\\\\n【兵家戰略】\\\\n吳起強調軍事組織的物質基礎與心理激勵。從地形、飼料、車軸保養、兵器防具，到最終士兵的作戰意願，環環相扣；再輔以賞罰分明與嚴守誠信，軍隊才能發揮最大戰力。"}},{"id":"wu-zi_ch-3_p-2","chapterId":"wu-zi_ch-3","order":2,"canonicalText":"武侯問曰：「兵何以為勝？」起對曰：「以治為勝。」又問曰：「不在眾寡？」對曰：「若法令不明，賞罰不信，金之不止，鼓之不進，雖有百萬，何益於用。所謂治者，居則有禮，動則有威，進不可當，退不可追，前卻有節，左右應麾，雖絕成陳，雖散成行。與之安，與之危，其眾可合而不可離，可用而不可疲，投之所往，天下莫當，名曰父子之兵。」","sentenceIds":["wu-zi_ch-3_p-2_s-1","wu-zi_ch-3_p-2_s-2","wu-zi_ch-3_p-2_s-3","wu-zi_ch-3_p-2_s-4","wu-zi_ch-3_p-2_s-5","wu-zi_ch-3_p-2_s-6","wu-zi_ch-3_p-2_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"魏武侯問道：「軍隊依靠什麼來取得勝利？」吳起回答說：「依靠治理嚴整來取得勝利。」武侯又問：「不在於兵多兵少嗎？」回答說：「如果法令不明確，賞罰不講誠信，鳴金軍隊不停，擊鼓軍隊不進，即使有百萬大軍，對作戰又有什麼好處？所謂治理嚴整，是指平時駐紮則有禮節規範，行動則有軍威震懾，進攻時銳不可擋，撤退時無法追擊，前後移動有節奏，左右轉向順應旗揮，即使隊伍被截斷也能就地成陣，即使隊伍被分散也能迅速排成行列。與士兵同甘共苦、共患難，士眾就能團結凝聚而不可離散，持續作戰而不顯疲憊，投向何處都無人能擋，這就叫做『父子之兵』。」","analysis":"【主題與背景】\\\\n本段深刻論述軍紀組織力（治）高於單純兵力數量（眾）的軍事哲理，並提出「父子之兵」的至高軍隊境界。\\\\n\\\\n【詞義與名物】\\\\n「以治為勝」：軍隊勝負取決於組織嚴密與訓練有素而非數量。「父子之兵」：將帥與士兵關係親如父子、生死相依的部隊。\\\\n\\\\n【兵家戰略】\\\\n吳起指出軍事治理的極致是部隊具備高度的彈性與韌性（絕成陳、散成行），且將帥與士卒建立深厚的感情信任，使軍隊具備強大的凝聚力與戰鬥意志。"}},{"id":"wu-zi_ch-3_p-3","chapterId":"wu-zi_ch-3","order":3,"canonicalText":"吳子曰：「凡行軍之道，無犯進止之節，無失飲食之適，無絕人馬之力。此三者，所以任其上令。任其上令，則治之所由生也。若進止不度，飲食不適，馬疲人倦而不解舍，所以不任其上令。上令既廢，以居則亂，以戰則敗。」","sentenceIds":["wu-zi_ch-3_p-3_s-1","wu-zi_ch-3_p-3_s-2","wu-zi_ch-3_p-3_s-3","wu-zi_ch-3_p-3_s-4","wu-zi_ch-3_p-3_s-5","wu-zi_ch-3_p-3_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"吳子說：「凡是行軍的法則，不要違反前進停止的節奏，不要失卻飲食調養的適度，不要耗盡人馬的體力。這三條，是用來貫徹上級命令的基礎。能夠貫徹上級命令，軍隊的嚴整治理就由此產生了。如果前進後退沒有限度，飲食調養不適當，馬匹疲憊人員倦怠卻不設營休息，這就會導致無法貫徹上級命令。上級命令一旦廢弛，駐紮就會混亂，作戰就會失敗。」","analysis":"【主題與背景】\\\\n本段強調行軍過程中的體力管理與作息節奏，指出合理的行軍管理是軍令暢通的物質保障。\\\\n\\\\n【詞義與名物】\\\\n「進止之節、飲食之適、無絕人馬之力」：行軍管理的「三不違」原則。「解舍」：放下裝備休息設營。\\\\n\\\\n【兵家戰略】\\\\n吳起深刻認識到士兵的生理與心理極限。將帥如果一味濫用軍令、無視士卒體力疲勞，軍令就會失去執行力，進而引發內部混亂與戰場潰敗。"}},{"id":"wu-zi_ch-3_p-4","chapterId":"wu-zi_ch-3","order":4,"canonicalText":"吳子曰：「凡兵戰之場，立屍之地。必死則生，幸生則死。其善將者，如坐漏船之中，伏燒屋之下，使智者不及謀，勇者不及怒，受敵可也。故曰：用兵之害，猶豫最大；三軍之災，生於狐疑。」","sentenceIds":["wu-zi_ch-3_p-4_s-1","wu-zi_ch-3_p-4_s-2","wu-zi_ch-3_p-4_s-3","wu-zi_ch-3_p-4_s-4","wu-zi_ch-3_p-4_s-5","wu-zi_ch-3_p-4_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"吳子說：「凡是戰場，都是堆積屍體的地方。懷著必死決心的就能生存，抱有僥倖苟活心理的就會死亡。善於指揮的將領，身處戰場就像坐在漏水的船中，趴在起火的房屋之下，使智者來不及謀劃私利，勇者來不及發怒抱怨，直接迎擊敵人就可以了。所以說：用兵最大的害處就是猶豫不決；三軍最大的災害就是產生狐疑猜忌。」","analysis":"【主題與背景】\\\\n本段論述戰場決斷力與士兵死戰心理的構建，警示「猶豫」與「狐疑」對軍事行動的毀滅性影響。\\\\n\\\\n【詞義與名物】\\\\n「必死則生，幸生則死」：著名的戰場生死辯證法。「坐漏船、伏燒屋」：形容置之死地而後生的絕境意識。\\\\n\\\\n【兵家戰略】\\\\n吳起強調戰場上決斷必須迅速果敢。將帥若能營造「無退路」的危機感，消除全軍的僥倖心理與猜忌，就能將全軍戰鬥力發揮到極致。"}},{"id":"wu-zi_ch-3_p-5","chapterId":"wu-zi_ch-3","order":5,"canonicalText":"吳子曰：「夫人當死其所不能，敗其所不便。故用兵之法，教戒為先。一人學戰，教成十人。十人學戰，教成百人。百人學戰，教成千人。千人學戰，教成萬人。萬人學戰，教成三軍。以近待遠，以佚待勞，以飽待飢。圓而方之，坐而起之，行而止之，左而右之，前而後之，分而合之，結而解之。每變皆習，乃授其兵。是謂將事。」","sentenceIds":["wu-zi_ch-3_p-5_s-1","wu-zi_ch-3_p-5_s-2","wu-zi_ch-3_p-5_s-3","wu-zi_ch-3_p-5_s-4","wu-zi_ch-3_p-5_s-5","wu-zi_ch-3_p-5_s-6","wu-zi_ch-3_p-5_s-7","wu-zi_ch-3_p-5_s-8","wu-zi_ch-3_p-5_s-9","wu-zi_ch-3_p-5_s-10","wu-zi_ch-3_p-5_s-11","wu-zi_ch-3_p-5_s-12"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"吳子說：「人往往會死於自己所不擅長的事，敗於自己所不習慣的環境。所以用兵的法則，必須以教育訓練為優先。一個人學會作戰，可以教成十個人；十個人學會作戰，可以教成百個人；百個人學會作戰，可以教成千個人；千個人學會作戰，可以教成萬個人；萬個人學會作戰，可以教成整個三軍。以近處等待遠道的敵人，以休息良好的部隊等待疲勞的敵人，以飽食的部隊等待飢餓的敵人。將圓陣變為方陣，讓部隊坐下或起立，前進或停止，向左或向右，向前或向後，分散或聚合，結陣或解陣。每一種變化都訓練熟練，然後才發給他們武器。這就叫做處理將帥的職務。」","analysis":"【主題與背景】\\\\n本段詳細論述軍事訓練的遞進層次與戰術陣形變化的日常演練，強調「教戒為先」。\\\\n\\\\n【詞義與名物】\\\\n「教戒為先」：作戰前必須經過系統軍事訓練。「以近待遠、以佚待勞、以飽待飢」：兵家優勢形勢營造法則。\\\\n\\\\n【兵家戰略】\\\\n吳起主張軍隊訓練必須由點到面層層推廣，並在武器發放前熟練掌握所有隊形變換與命令反應，從而在戰場上實現以逸待勞、靈活應變。"}},{"id":"wu-zi_ch-3_p-6","chapterId":"wu-zi_ch-3","order":6,"canonicalText":"吳子曰：「教戰之令，短者持矛戟，長者持弓弩，強者持旌旗，勇者持金鼓，弱者給冢養，智者為謀主。鄉里相比，什伍相保。一鼓整兵，二鼓習陳，三鼓趨食，四鼓嚴辨，五鼓就行。聞鼓聲合，然後舉旗。」","sentenceIds":["wu-zi_ch-3_p-6_s-1","wu-zi_ch-3_p-6_s-2","wu-zi_ch-3_p-6_s-3","wu-zi_ch-3_p-6_s-4","wu-zi_ch-3_p-6_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"吳子說：「教育作戰的軍令：身材矮小者拿槍戟近戰兵器，身材高大者拿弓弩遠射兵器，體力強壯者舉旌旗，勇敢無畏者擊金鼓，體弱者從事後勤伙食，聰明有智謀者擔任參謀。鄉里鄰居互相依託，什伍編制互相擔保。一聲鼓響整理兵器，二聲鼓響演練陣形，三聲鼓響前去就餐，四聲鼓響嚴密整頓防備，五聲鼓響即刻開赴軍陣。聽到鼓聲合拍統一，然後舉旗出發。」","analysis":"【主題與背景】\\\\n本段規定了兵種武器配備、士兵編組與鼓號軍令系統的具體實施規範。\\\\n\\\\n【詞義與名物】\\\\n「長短兵器分工」：依身材體質分配兵器。「什伍相保」：基於同鄉熟人的基聯防體制。「五鼓之令」：軍隊日常營務與臨戰號令流程。\\\\n\\\\n【兵家戰略】\\\\n吳起將人盡其才、物盡其用的原則引入軍隊配置，並透過熟人社會的社交紐帶（什伍相保）與標準化鼓號信號，極大降低了戰場指揮溝通成本。"}},{"id":"wu-zi_ch-3_p-7","chapterId":"wu-zi_ch-3","order":7,"canonicalText":"武侯問曰：「三軍進止。豈有道乎？」起對曰：「無當天竈，無當龍頭。天竈者，大谷之口。龍頭者，大山之端。必左青龍，右白虎，前朱雀，後玄武，招搖在上，從事於下。將戰之時，審候風所從來。風順致呼而從之，風逆堅陳以待之。」","sentenceIds":["wu-zi_ch-3_p-7_s-1","wu-zi_ch-3_p-7_s-2","wu-zi_ch-3_p-7_s-3","wu-zi_ch-3_p-7_s-4","wu-zi_ch-3_p-7_s-5","wu-zi_ch-3_p-7_s-6","wu-zi_ch-3_p-7_s-7","wu-zi_ch-3_p-7_s-8","wu-zi_ch-3_p-7_s-9"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"魏武侯問道：「三軍的前進與停止，難道有法則規律嗎？」吳起回答說：「不要正對著『天竈』扎營，不要正對著『龍頭』扎營。所謂天竈，是指大山谷的谷口；所謂龍頭，是指大山的端頭頂峯。布陣必須左邊有青龍（水流），右邊有白虎（長道），前有朱雀（開闊地），後有玄武（高山地形），招搖星旗在上指引，部隊在下跟從行動。準備作戰時，仔細審察風向從何處吹來。風向順風就大聲呼喊順風追擊，風向逆風就堅固陣勢嚴陣以待。」","analysis":"【主題與背景】\\\\n本段論述地理選擇（安營紮寨）與戰場風向氣候利用的軍事地形學法則。\\\\n\\\\n【詞義與名物】\\\\n「天竈、龍頭」：危險不利安營的地形（谷口風大易受伏、山頂無水易被圍）。「左青龍右白虎前朱雀後玄武」：古代軍隊陣地四方地理防衛定位。\\\\n\\\\n【兵家戰略】\\\\n吳起利用傳統四象方位表達戰術地形選擇，要求部隊避免陷入谷口或山頂等絕地，並善於根據風向順逆調整進攻與防禦策略。"}},{"id":"wu-zi_ch-3_p-8","chapterId":"wu-zi_ch-3","order":8,"canonicalText":"武侯問曰：「凡畜卒騎，豈有方乎？」起對曰：「夫馬必安其處所，適其水草，節其飢飽。冬則溫燒，夏則涼廡。刻剔毛鬣，謹落四下。戢其耳目，無令驚駭。習其馳逐，閑其進止。人馬相親，然後可使。車騎之具，鞍、勒、銜、轡，必令完堅。凡馬不傷於末，必傷於始；不傷於飢，必傷於飽。日暮道遠，必數上下。寧勞於人，慎無勞馬。常令有餘，備敵覆我。能明此者，橫行天下。」","sentenceIds":["wu-zi_ch-3_p-8_s-1","wu-zi_ch-3_p-8_s-2","wu-zi_ch-3_p-8_s-3","wu-zi_ch-3_p-8_s-4","wu-zi_ch-3_p-8_s-5","wu-zi_ch-3_p-8_s-6","wu-zi_ch-3_p-8_s-7","wu-zi_ch-3_p-8_s-8","wu-zi_ch-3_p-8_s-9","wu-zi_ch-3_p-8_s-10","wu-zi_ch-3_p-8_s-11","wu-zi_ch-3_p-8_s-12","wu-zi_ch-3_p-8_s-13","wu-zi_ch-3_p-8_s-14","wu-zi_ch-3_p-8_s-15"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"魏武侯問道：「養育訓練步兵與騎兵，難道有具體方法嗎？」吳起回答說：「馬匹必須使其居住處所安定，水草適宜，飲食飢飽有節制。冬天則設法保暖，夏天則保持涼爽。定期修剪毛鬣，謹慎釘好四蹄蹄鐵。使其耳目收斂不受驚嚇，練習其奔跑追逐，熟練其前進停止。人與馬親近信任，然後才可以使喚作戰。戰車與騎兵的裝備，鞍、勒、銜、轡，必須保持完好堅固。凡馬匹不受傷於後天，必受傷於開頭；不受傷於飢餓，必受傷於過飽。日落路遠之時，必須多次下馬步行。寧可讓人勞累，謹慎切勿使馬勞累。常使馬匹保持餘力，以防備敵人突襲覆滅我們。能明白這些道理的人，就能橫行天下。」","analysis":"【主題與背景】\\\\n本段詳細論述騎兵與馬匹養護管理、裝備保養的軍事後勤學細節。\\\\n\\\\n【詞義與名物】\\\\n「畜卒騎」：步兵與騎兵的養育管理。「寧勞於人，無勞於馬」：戰略後勤中保護騎兵核心戰鬥資源（戰馬）的至理名言。\\\\n\\\\n【兵家戰略】\\\\n吳起展現了極其細緻的後勤管理思維。戰馬是古代軍隊機動力的核心，通過節制飲食、定期保養裝備與避免過度勞累，保持馬匹戰鬥餘力，方能確保突發狀況下部隊的生存與勝算。"}},{"id":"wu-zi_ch-4_p-1","chapterId":"wu-zi_ch-4","order":1,"canonicalText":"吳子曰：「夫總文武者，軍之將也。兼剛柔者，兵之事也。凡人論將，常觀於勇。勇之於將，乃數分之一爾。夫勇者必輕合，輕合而不知利，未可也。故將之所慎者五：一曰理，二曰備，三曰果，四曰戒，五曰約。理者，治眾如治寡。備者，出門如見敵。果者，臨敵不懷生。戒者，雖克如始戰。約者，法令省而不煩。受命而不辭，敵破而後言返，將之禮也。故師出之日，有死之榮，無生之辱。」","sentenceIds":["wu-zi_ch-4_p-1_s-1","wu-zi_ch-4_p-1_s-2","wu-zi_ch-4_p-1_s-3","wu-zi_ch-4_p-1_s-4","wu-zi_ch-4_p-1_s-5","wu-zi_ch-4_p-1_s-6","wu-zi_ch-4_p-1_s-7","wu-zi_ch-4_p-1_s-8","wu-zi_ch-4_p-1_s-9","wu-zi_ch-4_p-1_s-10","wu-zi_ch-4_p-1_s-11","wu-zi_ch-4_p-1_s-12","wu-zi_ch-4_p-1_s-13","wu-zi_ch-4_p-1_s-14"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"吳子說：「統轄文德與武備的人，是軍隊的將領；兼備剛強與柔和的人，是軍事的主導。一般人討論將領，常常只看重英勇。英勇對於將領來說，不過是諸多素質中的幾分之一罷了。勇敢的人 picnic 輕率交戰，輕率交戰而不懂是否有利，那是不可取的。所以將領所應謹慎把握的有五條：一是『理』，二是『備』，三是『果』，四是『戒』，五是『約』。理，是指治理大軍如治理少數人一樣條理清晰；備，是指離門出征如隨時面對敵人一樣警惕；果，是指臨敵決戰絕不懷戀苟活；戒，是指即使戰勝敵人也如初始開戰一樣謹慎；約，是指法令簡省而不煩瑣雜亂。接受使命而不推辭，打敗敵人之後才談回師，這是將領的禮節。所以軍隊出征之日，有戰死的榮譽，沒有苟活的屈辱。」","analysis":"【主題與背景】\\\\n本段系統界定了理想將領的綜合素質，提出著名的「將之五慎」（理、備、果、戒、約），反對將將領素質簡化為單純勇猛。\\\\n\\\\n【詞義與名物】\\\\n「將之五慎」：理（條理）、備（防備）、果（果決）、戒（戒懼）、約（約束簡明）。「受命不辭，敵破言返」：將領忠誠履行軍事使命的倫理原則。\\\\n\\\\n【兵家戰略】\\\\n吳起強調將領是文武兼備、剛柔相濟的複合型領導者。勇敢若缺乏理性評估會導致盲目冒險，唯有治理有條、防備嚴密、決斷果敢、勝不驕矜、法令簡明，才能成為無敵良將。"}},{"id":"wu-zi_ch-4_p-2","chapterId":"wu-zi_ch-4","order":2,"canonicalText":"吳子曰：「凡兵有四機：一曰氣機，二曰地機，三曰事機，四曰力機。三軍之眾，百萬之師，張設輕重，在於一人，是謂氣機。路狹道險，名山大塞，十夫所守，千夫不過，是謂地機。善行間諜，輕兵往來，分散其眾，使其君臣相怨，上下相咎，是謂事機。車堅管轄，舟利櫓楫，士習戰陳，馬閑馳逐，是謂力機。知此四者，乃可為將。然其威、德、仁、勇，必足以率下安眾，怖敵決疑。施令而下不犯，所在寇不敢敵。得之國強，去之國亡。是謂良將。」","sentenceIds":["wu-zi_ch-4_p-2_s-1","wu-zi_ch-4_p-2_s-2","wu-zi_ch-4_p-2_s-3","wu-zi_ch-4_p-2_s-4","wu-zi_ch-4_p-2_s-5","wu-zi_ch-4_p-2_s-6","wu-zi_ch-4_p-2_s-7","wu-zi_ch-4_p-2_s-8","wu-zi_ch-4_p-2_s-9","wu-zi_ch-4_p-2_s-10","wu-zi_ch-4_p-2_s-11"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"本段典籍核心大意在於闡述現代維度的價值理念。具體而言，文言語意涵蓋了有關先生、講述、講述、講述、萬物基址、講述、講述、眾人、規律與原理、陵谷山嶽、萬物基址、統治者、輔佐之官、素養品行、關愛博愛、社稷諸侯、社稷諸侯的深層觀點，揭示了事物運作與組織管理之法則。全段旨在提醒人們在處世與決策時應保持清醒的洞察力。〔《吳子》〈論將〉第22節導讀〕","analysis":"【主旨】本段聚焦於《吳子》的核心議題，解析了當前章節的精髓與核心觀念。\\n【關鍵詞義】「吳」──古漢語核心意象與經典表達；「子」──古漢語核心意象與經典表達；「曰」──古漢語核心意象與經典表達；「凡」──古漢語核心意象與經典表達\\n【思想脈絡】段落結構嚴謹，語意層次分明。從「吳」出發，漸次遞進至全篇哲理宏旨。\\n【當代啟示】提示現代人在面對複雜情境時，應汲取古代智慧，保持理性與定力。"}},{"id":"wu-zi_ch-4_p-3","chapterId":"wu-zi_ch-4","order":3,"canonicalText":"吳子曰：「夫鼙鼓金鐸，所以威耳。旌旗麾幟，所以威目。禁令刑罰，所以威心。耳威於聲，不可不清。目威於色，不可不明。心威於刑，不可不嚴。三者不立，雖有其國，必敗於敵。故曰：將之所麾，莫不從移；將之所指，莫不前死。」","sentenceIds":["wu-zi_ch-4_p-3_s-1","wu-zi_ch-4_p-3_s-2","wu-zi_ch-4_p-3_s-3","wu-zi_ch-4_p-3_s-4","wu-zi_ch-4_p-3_s-5","wu-zi_ch-4_p-3_s-6","wu-zi_ch-4_p-3_s-7","wu-zi_ch-4_p-3_s-8","wu-zi_ch-4_p-3_s-9","wu-zi_ch-4_p-3_s-10"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"吳子說：「小鼓大鼓金鐸鈴響，是用來震懾與聽從耳力的；旌旗旗幟揮舞，是用來震懾與引導目力的；禁令刑罰嚴明，是用來震懾與約束心力的。耳力受聲音震懾，聲音不可不清晰；目力受色彩震懾，色彩不可不明確；心力受刑罰震懾，刑罰不可不嚴格。這三者如果不能樹立，雖然擁有國家，也必定被敵人擊敗。所以說：將領旗揮所指，沒有人不跟著移動；將領寶劍所指，沒有人不向前赴死。」","analysis":"【主題與背景】\\\\n本段論述軍隊指揮通訊系統（聲、色、刑）對聽覺、視覺與心理的控制機制。\\\\n\\\\n【詞義與名物】\\\\n「威耳、威目、威心」：通過聽覺（鼓鐸）、視覺（旗幟）與心理（刑罰）實現高度集中的指揮控制。\\\\n\\\\n【兵家戰略】\\\\n吳起深刻闡明戰場號令視覺化與聽覺化的技術細節。聲響清晰、旗幟明確、軍紀嚴明，方能使萬千士兵如一人般響應將領指揮，達到「莫不前死」的控制力。"}},{"id":"wu-zi_ch-4_p-4","chapterId":"wu-zi_ch-4","order":4,"canonicalText":"吳子曰：「凡戰之要，必先占其將而察其才。因形用權，則不勞而功舉。其將愚而信人，可詐而誘；貪而忽名，可貨而賂；輕變無謀，可勞而困。上富而驕，下貧而怨，可離而間。進退多疑，其眾無依，可震而走。士輕其將而有歸志，塞易開險，可邀而取。進道易，退道難，可來而前。進道險，退道易，可薄而擊。居軍下濕，水無所通，霖雨數至，可灌而沈。居軍荒澤，草楚幽穢，風飆數至，可焚而滅。停久不移，將士懈怠，其軍不備，可潛而襲。」","sentenceIds":["wu-zi_ch-4_p-4_s-1","wu-zi_ch-4_p-4_s-2","wu-zi_ch-4_p-4_s-3","wu-zi_ch-4_p-4_s-4","wu-zi_ch-4_p-4_s-5","wu-zi_ch-4_p-4_s-6","wu-zi_ch-4_p-4_s-7","wu-zi_ch-4_p-4_s-8","wu-zi_ch-4_p-4_s-9","wu-zi_ch-4_p-4_s-10","wu-zi_ch-4_p-4_s-11","wu-zi_ch-4_p-4_s-12","wu-zi_ch-4_p-4_s-13","wu-zi_ch-4_p-4_s-14"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"吳子說：「凡是作戰的要領，必定要先推察敵方將領的性格並審察其才能。順應敵情採取權變戰術，就能不費大功告成。敵方將領如果愚蠢而輕信他人，可以用詐謀進行誘騙；如果貪婪而忽視名聲，可以用財貨進行賄賂；如果輕率易變缺乏謀略，可以用頻繁騷擾使其疲憊困頓；如果上層富有而驕縱、下層貧困而怨恨，可以用離間計進行分化；如果進退多疑、部眾無所適從，可以用震懾戰術使其逃跑；如果士兵輕視其將領且有回家心思，可以堵塞平坦道路、留出險要通道，在要衝伏擊討伐；如果敵人前進道路平坦、後退道路困難，可以引誘其深入然後進攻；如果敵人前進道路險要、後退道路平坦，可以逼近並打擊它；如果敵軍駐紮低窪潮濕之地、水流無法疏通，連續連降大雨，可以用大水淹沒沉沒它；如果敵軍駐紮荒野沼澤、草木幽深雜亂，狂風屢次吹來，可以用火攻將其焚毀滅絕；如果敵軍停駐許久不移動，將士懈怠防備鬆弛，可以用潛伏進行襲擊。」","analysis":"【主題與背景】\\\\n本段詳盡論述針對敵將性格缺陷（愚、貪、輕、驕、疑）與敵軍駐紮環境（水、火、地形）採取的十二種權變打擊戰術。\\\\n\\\\n【詞義與名物】\\\\n「佔將察才」：評估敵方指揮官的心理與性格弱點。「因形用權」：根據敵人具體形態變化靈活運用權變戰術。\\\\n\\\\n【兵家戰略】\\\\n吳起主張「針對性格與環境缺陷破敵」。敵將性格上的貪婪、多疑、輕率，以及敵軍駐地的水火地形隱患，都是兵家可以無損獲勝的打擊突破口。"}},{"id":"wu-zi_ch-4_p-5","chapterId":"wu-zi_ch-4","order":5,"canonicalText":"武侯問曰：「兩軍相望，不知其將，我欲相之，其術如何？」起對曰：「令賤而勇者，將輕銳以嘗之。務於北，無務於得，觀敵之來，一坐一起，其政以理，其追北佯為不及，其見利佯為不知，如此將者，名為智將，勿與戰矣。若其眾讙譁，旌旗煩亂，其卒自行自止，其兵或縱或橫，其追北恐不及，見利恐不得，此為愚將，雖眾可獲。」","sentenceIds":["wu-zi_ch-4_p-5_s-1","wu-zi_ch-4_p-5_s-2","wu-zi_ch-4_p-5_s-3","wu-zi_ch-4_p-5_s-4","wu-zi_ch-4_p-5_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"魏武侯問道：「兩軍對峙相望，不知道敵方將領的底細，我想觀察評估他，有什麼戰術方法嗎？」吳起回答說：「派遣身分低微卻勇敢的人，率領輕捷精銳的部隊去試探敵人。務必偽裝敗退，不要爭取獲勝，觀察敵人的追擊行動：如果敵軍一坐一起秩序井然，其政治軍紀條理分明，追擊敗兵時假裝追不上，見到利益時假裝不知道，遇到這樣的將領，名為『智將』，切勿輕易與他交戰。如果敵軍部眾喧嘩騷亂，旌旗雜亂無章，士兵自作主張走走停停，兵器橫七豎八，追擊敗兵時唯恐追不上，見到利益時唯恐得不到，這就是『愚將』，雖然人數眾多也可以將其俘獲。」","analysis":"【主題與背景】\\\\n本段介紹通過「輕兵試探（佯敗）」來偵察評估敵將智愚的戰術實踐方法。\\\\n\\\\n【詞義與名物】\\\\n「相將之術」：觀察敵將戰術反應與軍紀狀態的偵察方法。「智將與愚將」：能保持沉著冷靜不貪小利者為智將，部隊騷亂貪利冒進者為愚將。\\\\n\\\\n【兵家戰略】\\\\n吳起設計了「佯敗誘敵」的測試模型。智將面對佯敗會保持警惕、防止伏兵；愚將則會貪利冒進、隊形大亂，將領的優劣在試探中一目瞭然。"}},{"id":"wu-zi_ch-5_p-1","chapterId":"wu-zi_ch-5","order":1,"canonicalText":"武侯問曰：「車堅馬良，將勇兵強，卒遇敵人，亂而失行，則如之何？」起對曰：「凡戰之法，晝以旌旗旛麾為節，夜以金鼓笳笛為節。麾左而左，麾右而右。鼓之則進，金之則止。二吹而行，再吹而聚，不從令者誅。三軍服威，士卒用命，則戰無彊敵，攻無堅陳矣。」","sentenceIds":["wu-zi_ch-5_p-1_s-1","wu-zi_ch-5_p-1_s-2","wu-zi_ch-5_p-1_s-3","wu-zi_ch-5_p-1_s-4","wu-zi_ch-5_p-1_s-5","wu-zi_ch-5_p-1_s-6","wu-zi_ch-5_p-1_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"魏武侯問道：「戰車堅固馬匹優良，將領勇敢士兵強壯，猝然遭遇敵人，部隊混亂而失去行列，該怎麼辦呢？」吳起回答說：「凡是作戰的法則，白天以旌旗旗幟為指揮節制，夜晚以金鼓笳笛為指揮節制。旗幟揮向左邊就向左，揮向右邊就向右。擊鼓就前進，鳴金就停止。吹一次號角就準備開行，吹二次號角就聚集集合，不聽從軍令的處斬。三軍服膺軍威，士卒聽從命令，戰鬥就沒有強敵，進攻就沒有堅固的陣勢了。」","analysis":"【主題與背景】\\\\n本段回答軍隊在遭遇戰中隊形混亂時，如何通過強大的晝夜信號與軍紀迅速恢復控制。\\\\n\\\\n【詞義與名物】\\\\n「晝旗夜鼓」：古代軍隊晝夜通訊控制標準。「吹笳號角」：用於集結與行動的軍用樂器信號。\\\\n\\\\n【兵家戰略】\\\\n吳起強調「信號嚴明」是應對突發遭遇戰的第一要務。平時養成對旗幟與鼓角信號的絕對服從，能在猝不及防的混亂中瞬間重構軍隊秩序。"}},{"id":"wu-zi_ch-5_p-2","chapterId":"wu-zi_ch-5","order":2,"canonicalText":"武侯問曰：「若敵眾我寡，為之柰何？」起對曰：「避之於易，邀之於阨。故曰：以一擊十，莫善於阨；以十擊百，莫善於險；以千擊萬，莫善於阻。今有少年卒起，擊金鳴鼓於阨路，雖有大眾，莫不驚動。故曰：用眾者務易，用少者務隘。」","sentenceIds":["wu-zi_ch-5_p-2_s-1","wu-zi_ch-5_p-2_s-2","wu-zi_ch-5_p-2_s-3","wu-zi_ch-5_p-2_s-4","wu-zi_ch-5_p-2_s-5","wu-zi_ch-5_p-2_s-6","wu-zi_ch-5_p-2_s-7","wu-zi_ch-5_p-2_s-8"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"魏武侯問道：「如果敵眾我寡，該怎麼辦呢？」吳起回答說：「在平坦開闊之地要避開敵軍，在險要狹窄之處要截擊敵軍。所以說：以一人打擊十人，沒有比狹窄要隘更好的地方；以十人打擊百人，沒有比險峻山道更好的地方；以千人打擊萬人，沒有比阻隔要衝更好的地方。如今如果有少數勇士突然發起，在狹路要隘擊金鳴鼓，敵人雖然人多，無不驚慌動搖。所以說：兵多者務求在平坦開闊地交戰，兵少者務求在狹隘險要處交戰。」","analysis":"【主題與背景】\\\\n本段論述「以少勝多」的地形戰略，提出「用眾者務易，用少者務隘」的經典名言。\\\\n\\\\n【詞義與名物】\\\\n「易與阨」：平坦開闊地（易）與狹窄險要處（阨）。「邀之於阨」：在敵軍無法展開大部隊的狹隘地形截擊。\\\\n\\\\n【兵家戰略】\\\\n吳起指出地形是兵力乘數器。兵少時必須將戰場限制在險關狹道，使敵人的兵力數量優勢無法展開，同時利用聲勢與伏擊造成敵軍心理恐慌。"}},{"id":"wu-zi_ch-5_p-3","chapterId":"wu-zi_ch-5","order":3,"canonicalText":"武侯問曰：「有師甚眾，既武且勇；背大險阻，右山左水；深溝高壘，守以彊弩；退如山移，進如風雨，糧食又多。難與長守。」對曰：「大哉問乎！非此車騎之力，聖人之謀也。能備千乘萬騎，兼之徒步，分為五軍，各軍一衢。夫五軍五衢，敵人必惑，莫之所加。敵人若堅守以固其兵，急行間諜以觀其慮。彼聽吾說，解之而去。不聽吾說，斬使焚書，分為五戰。戰勝勿追，不勝疾歸。如是佯北，安行疾鬭，一結其前，一絕其後。兩軍𠾑枚，或左或右，而襲其處。五軍交至，必有其力。此擊彊之道也。」","sentenceIds":["wu-zi_ch-5_p-3_s-1","wu-zi_ch-5_p-3_s-2","wu-zi_ch-5_p-3_s-3","wu-zi_ch-5_p-3_s-4","wu-zi_ch-5_p-3_s-5","wu-zi_ch-5_p-3_s-6","wu-zi_ch-5_p-3_s-7","wu-zi_ch-5_p-3_s-8","wu-zi_ch-5_p-3_s-9","wu-zi_ch-5_p-3_s-10","wu-zi_ch-5_p-3_s-11","wu-zi_ch-5_p-3_s-12","wu-zi_ch-5_p-3_s-13","wu-zi_ch-5_p-3_s-14","wu-zi_ch-5_p-3_s-15","wu-zi_ch-5_p-3_s-16","wu-zi_ch-5_p-3_s-17","wu-zi_ch-5_p-3_s-18"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"魏武侯問道：「如果有敵軍人數極多，既武藝高強又勇敢；背靠大險阻地形，右邊是山陵左邊是水流；築有深溝高壘，用強弩堅守；後退時如山嶽移動，前進時如風雨交加，糧食儲備又多，很難與其長期對峙僵持。」吳起回答說：「這是多麼高明的大問題啊！這不是普通戰車騎兵所能解決的，必須靠聖人般的謀略纔行。應當裝備千乘戰車萬匹騎兵，加上步兵，分為五支軍隊，每軍佔據一條要道。五軍五道，敵人必定困惑，不知道該防備哪裡。敵人如果堅守以固守其部隊，迅速派遣間諜去觀察其企圖想法。敵若聽信我方說辭間諜勸誘，解圍離去；若不聽我方說辭，殺害使者焚燒書信，就分為五路發起進攻。戰勝了不要盲目追擊，不勝就迅速撤回。像這樣佯裝敗退，從容撤退快速戰鬥，一路牽制敵前，一路切斷敵後。兩軍口銜枚默默行動，或左或右，襲擊敵軍營寨。五軍交替到達，必定發揮巨大威力。這就是打擊強大敵軍的途徑。」","analysis":"【主題與背景】\\\\n本段回答如何破解佔盡地形、兵力、糧餉優勢且防守堅固之敵的戰略巨題。\\\\n\\\\n【詞義與名物】\\\\n「五軍五衢」：將部隊分為五路多線並進，分散並惑亂敵軍集中兵力。「銜枚」：口含木枚防止部隊行動發出聲音，進行隱蔽夜襲。\\\\n\\\\n【兵家戰略】\\\\n吳起針對強敵提出了「多線心理威嚇、間諜分化、多路佯攻與機動襲擊」的複合戰略。不硬攻堅壘，而是通過多路機動與襲擊切斷敵人糧道後方，動搖其堅守意志。"}},{"id":"wu-zi_ch-5_p-4","chapterId":"wu-zi_ch-5","order":4,"canonicalText":"武侯問曰：「敵近而薄我，欲去無路，我眾甚懼，為之柰何？」對曰：「為此之術，若我眾彼寡，各分而乘之。彼眾我寡，以方從之。從之無息，雖眾可服。」","sentenceIds":["wu-zi_ch-5_p-4_s-1","wu-zi_ch-5_p-4_s-2","wu-zi_ch-5_p-4_s-3","wu-zi_ch-5_p-4_s-4","wu-zi_ch-5_p-4_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"魏武侯問道：「敵人逼近並迫近我們，想撤退又沒有退路，我方大軍非常恐懼，該怎麼辦呢？」吳起回答說：「應對這種戰況的方法：如果我眾敵寡，分兵多路乘勝追擊打擊敵人；如果敵眾我寡，就集中兵力組成方陣連續衝擊敵人。持續攻擊不給敵人休息喘息之機，敵人雖然人數眾多也可以降服。」","analysis":"【主題與背景】\\\\n本段論述遭遇絕境逼近、軍心恐懼時的應急進攻戰術。\\\\n\\\\n【詞義與名物】\\\\n「薄我」：逼迫接近我軍。「以方從之」：組成緊密方陣進行集中突擊。\\\\n\\\\n【兵家戰略】\\\\n吳起主張「在絕境中以攻代守」。當陷入敵眾我寡且無路可退的恐懼中時，唯有集中兵力組成堅固方陣連續不斷髮起衝擊，以極致的進攻節奏打亂敵人部署。"}},{"id":"wu-zi_ch-5_p-5","chapterId":"wu-zi_ch-5","order":5,"canonicalText":"武侯問曰：「若遇敵於谿谷之間，傍多險阻，彼眾我寡，為之奈何？」起對曰：「諸丘陵、林谷、深山、大澤，疾行亟去，勿得從容。若高山深谷，卒然相遇，必先鼓譟而乘之。進弓與弩，且射且虜。審察其政，亂則擊之勿疑。」","sentenceIds":["wu-zi_ch-5_p-5_s-1","wu-zi_ch-5_p-5_s-2","wu-zi_ch-5_p-5_s-3","wu-zi_ch-5_p-5_s-4","wu-zi_ch-5_p-5_s-5","wu-zi_ch-5_p-5_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"魏武侯問道：「如果在溪谷之間遭遇敵人，兩旁大多是險阻地形，敵眾我寡，該怎麼辦呢？」吳起回答說：「凡行經丘陵、森林山谷、深山、大沼澤等地形，必須快速通過迅速離開，切不可從容遲緩。如果在高山深谷中突然與敵人相遇，必定要先大聲擊鼓吶喊乘勢進攻，推前弓與弩，邊射擊邊俘獲。仔細審察敵軍的政治與組織狀態，若敵人混亂就果斷打擊它，絕不猶豫。」","analysis":"【主題與背景】\\\\n本段論述在山谷沼澤等複雜險惡地形中遭遇強敵時的快速通過與先發制人戰術。\\\\n\\\\n【詞義與名物】\\\\n「疾行亟去」：在不利地形快速通過不作停留。「先鼓譟而乘之」：在山谷突然遭遇時先聲奪人發起搶攻。\\\\n\\\\n【兵家戰略】\\\\n吳起強調險惡地形的風險管理。在山谷沼澤不可停留防守；若遭遇敵軍，必須搶先發起聲勢與遠射打擊，破壞敵方組織，趁敵混亂發動反擊。"}},{"id":"wu-zi_ch-5_p-6","chapterId":"wu-zi_ch-5","order":6,"canonicalText":"武侯問曰：「左右高山，地甚狹迫，卒遇敵人，擊之不敢，去之不得，為之奈何？」起對曰：「此謂谷戰，雖眾不用。募吾材士與敵相當，輕足利兵以為前行，分車列騎隱於四旁，相去數里，無見其兵，敵必堅陳，進退不敢。於是出旌列旆，行出山外營之，敵人必懼。車騎挑之，勿令得休。此谷戰之法也。」","sentenceIds":["wu-zi_ch-5_p-6_s-1","wu-zi_ch-5_p-6_s-2","wu-zi_ch-5_p-6_s-3","wu-zi_ch-5_p-6_s-4","wu-zi_ch-5_p-6_s-5","wu-zi_ch-5_p-6_s-6","wu-zi_ch-5_p-6_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"魏武侯問道：「左右都是高山，地形非常狹窄逼迫，猝然遭遇敵人，不敢進攻，又無法撤退，該怎麼辦呢？」吳起回答說：「這叫做『谷戰』，敵人兵力雖然多也無法展開發揮。招募我方精銳勇士與敵人相當，以腳步輕快兵器鋒利者作為前鋒，將戰車與騎兵隱蔽在四旁山谷中，相距數裏，不讓敵人看見兵力。敵人必定堅守軍陣，不敢進退。此時展示旌旗排列旗幟，走出山外築營安紮，敵人必定恐懼。再派車騎進行挑釁騷擾，不讓敵人得到休息。這就是谷戰的戰法。」","analysis":"【主題與背景】\\\\n本段專題論述狹山谷遭遇戰（谷戰）的解圍與佯動誘敵戰術。\\\\n\\\\n【詞義與名物】\\\\n「谷戰」：狹窄山谷中的特殊戰鬥形態。「行出山外營之」：在山谷外張揚聲勢安營紮寨，營造包圍敵人的錯覺。\\\\n\\\\n【兵家戰略】\\\\n吳起利用山谷地形限制敵軍數量的特點，一方面以精銳前鋒卡位，另一方面在山谷外展示大軍假象，造成敵軍恐懼，再以車騎持續騷擾疲敵。"}},{"id":"wu-zi_ch-5_p-7","chapterId":"wu-zi_ch-5","order":7,"canonicalText":"武侯問曰：「吾與敵相遇大水之澤，傾輪沒轅，水薄車騎，舟楫不設，進退不得，為之奈何？」起對曰：「此謂水戰，無用車騎，且留其傍。登高四望，必得水情。知其廣狹，盡其淺深，乃可為奇以勝之。敵若絕水，半渡而薄之。」","sentenceIds":["wu-zi_ch-5_p-7_s-1","wu-zi_ch-5_p-7_s-2","wu-zi_ch-5_p-7_s-3","wu-zi_ch-5_p-7_s-4","wu-zi_ch-5_p-7_s-5","wu-zi_ch-5_p-7_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"魏武侯問道：「我和敵人相遇在大水沼澤之中，車輪傾斜車轅淹沒，水流逼近戰車騎兵，沒有準備舟船，進退不得，該怎麼辦呢？」吳起回答說：「這叫做『水戰』，無法使用戰車騎兵，暫且將車騎留在水邊。登高向四處張望，必定要掌握水流地形狀況。瞭解水域的寬窄，探明水流的深淺，然後才可以設奇兵來戰勝敵人。敵人如果渡水前來，就在敵軍半渡時迎頭打擊它。」","analysis":"【主題與背景】\\\\n本段論述沼澤水窪地形中戰車騎兵受阻（水戰）時的偵察與「半渡而擊」戰術。\\\\n\\\\n【詞義與名物】\\\\n「水戰」：在水窪沼澤地發生的戰鬥。「半渡而薄之」：敵軍渡水渡到一半時發起打擊。\\\\n\\\\n【兵家戰略】\\\\n吳起指出車騎陷入水窪時切不可強行作戰。應先登高偵察水情，利用地形佈置奇兵；一旦敵軍試圖渡水追擊，即把握「半渡而擊」的戰術視窗發起反擊。"}},{"id":"wu-zi_ch-5_p-8","chapterId":"wu-zi_ch-5","order":8,"canonicalText":"武侯問曰：「天久連雨，馬陷車止，四面受敵，三軍驚駭，為之奈何？」起對曰：「凡用車者，陰濕則停，陽燥則起；貴高賤下，馳其強車；若進若止，必從其道。敵人若起，必逐其跡。」","sentenceIds":["wu-zi_ch-5_p-8_s-1","wu-zi_ch-5_p-8_s-2","wu-zi_ch-5_p-8_s-3","wu-zi_ch-5_p-8_s-4","wu-zi_ch-5_p-8_s-5","wu-zi_ch-5_p-8_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"魏武侯問道：「天氣長期連降大雨，戰馬陷泥戰車停滯，四面遭受敵人包圍，三軍驚慌害怕，該怎麼辦呢？」吳起回答說：「凡是使用戰車的原則，陰雨潮濕時就停止行動，晴朗乾燥時就開起行動；尊崇高處避開低窪，在堅硬地面馳騁精良戰車；無論前進還是停止，必定要順應道路。敵人如果行動發起攻擊，必定要順著敵人的足跡進行追擊打擊。」","analysis":"【主題與背景】\\\\n本段論述連雨泥濘、戰車陷泥且四面受敵時的地理選擇與跟蹤反擊戰術。\\\\n\\\\n【詞義與名物】\\\\n「貴高賤下」：戰車作戰選擇高處堅硬地帶、避開低窪泥濘之地的原則。「逐其跡」：順著敵軍踩出的安全路徑反擊。\\\\n\\\\n【兵家戰略】\\\\n吳起強調氣候與路況對戰車作戰的制約。在泥濘困境中應迅速撤往高處堅地；敵軍若能推進，說明敵軍路徑安全，順著敵軍足跡反擊即可化解被圍危機。"}},{"id":"wu-zi_ch-5_p-9","chapterId":"wu-zi_ch-5","order":9,"canonicalText":"武侯問曰：「暴寇卒來，掠吾田野，取吾牛羊，則如之何？」","sentenceIds":["wu-zi_ch-5_p-9_s-1","wu-zi_ch-5_p-9_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"魏武侯問道：「暴虐的敵寇突然到來，搶劫我們的田野，掠奪我們的牛羊，該怎麼辦呢？」","analysis":"【主題與背景】\\\\n本段是魏武侯關於敵寇突然入侵、掠奪民間財物時如何應對的戰術提問。\\\\n\\\\n【詞義與名物】\\\\n「暴寇」：突然入侵、以掠奪財物為目的的敵方騎兵或散兵。\\\\n\\\\n【兵家戰略】\\\\n此段為問句，引出下一段吳起關於「善守勿應、趁敵返程疲憊追擊」的精彩解答。"}},{"id":"wu-zi_ch-5_p-10","chapterId":"wu-zi_ch-5","order":10,"canonicalText":"起對曰：「暴寇之來，必慮其強，善守勿應。彼將暮去，其裝必重，其心必恐，還退務速，必有不屬。追而擊之，其兵可覆。」","sentenceIds":["wu-zi_ch-5_p-10_s-1","wu-zi_ch-5_p-10_s-2","wu-zi_ch-5_p-10_s-3","wu-zi_ch-5_p-10_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"吳起回答說：「暴寇突然到來，必定要考慮敵人的強悍鋒芒，堅善防守切勿輕易迎戰。敵人到了榜晚準備離去時，搶掠的裝備財物必定沉重，內心必定害怕遭伏，撤退必定求快，隊伍必定脫節不相連屬。此時出兵追擊打擊敵人，敵人的軍隊就可以全殲覆滅。」","analysis":"【主題與背景】\\\\n本段解答應對敵寇掠奪的戰術——避其初來之銳氣，待敵滿載而歸、隊形脫節時發起追擊全殲。\\\\n\\\\n【詞義與名物】\\\\n「善守勿應」：敵初來鋒芒正盛時堅守不出。「還退務速，必有不屬」：敵攜重物急退時隊伍必然斷裂脫節。\\\\n\\\\n【兵家戰略】\\\\n吳起精確抓住了掠奪型敵寇的心理與行動規律。敵寇來時氣勢洶洶，去時背負重物、內心恐慌且隊伍脫節，此時發起追擊能以極小代價殲滅敵軍。"}},{"id":"wu-zi_ch-5_p-11","chapterId":"wu-zi_ch-5","order":11,"canonicalText":"吳子曰：「凡攻敵圍城之道，城邑既破，各入其宮。御其祿秩，收其器物。軍之所至，無刊其木、發其屋、取其粟、殺其六畜、燔其積聚，示民無殘心。其有請降，許而安之。」","sentenceIds":["wu-zi_ch-5_p-11_s-1","wu-zi_ch-5_p-11_s-2","wu-zi_ch-5_p-11_s-3","wu-zi_ch-5_p-11_s-4","wu-zi_ch-5_p-11_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"吳子說：「凡是攻打敵人圍守城池的法則，城池攻破之後，各部隊進入相應宮室官署。掌控其官爵奉祿檔案，接收其武器器物。軍隊所到之處，不得砍伐樹木、拆毀房屋、搶奪糧食、屠殺六畜、焚燒囤積物資，向敵國百姓展示沒有殘害之心。如果有請求投降的，應當允許並安撫他們。」","analysis":"【主題與背景】\\\\n本段論述破城之後的城市接管政策與嚴明軍紀，強調「示民無殘心」的政治安撫戰略。\\\\n\\\\n【詞義與名物】\\\\n「御祿秩」：接管掌控敵國的官制與檔案紀錄。「無殘心」：展示不殘害平民百姓的正義之師形象。\\\\n\\\\n【兵家戰略】\\\\n吳起將攻城戰延伸至政治接管層面。嚴禁破壞農木民房糧草，安撫降民，能最大限度降低敵國反抗情緒，快速穩定戰後秩序，實現真正的軍事與政治勝利。"}},{"id":"wu-zi_ch-6_p-1","chapterId":"wu-zi_ch-6","order":1,"canonicalText":"武侯問曰：「嚴刑明賞，足以勝乎？」起對曰：「嚴明之事，臣不能悉。雖然，非所恃也。夫發號布令而人樂聞，興師動眾而人樂戰，交兵接刃而人樂死。此三者，人主之所恃也。」","sentenceIds":["wu-zi_ch-6_p-1_s-1","wu-zi_ch-6_p-1_s-2","wu-zi_ch-6_p-1_s-3","wu-zi_ch-6_p-1_s-4","wu-zi_ch-6_p-1_s-5","wu-zi_ch-6_p-1_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"魏武侯問道：「嚴明刑罰、明確賞賜，足可以取得勝利嗎？」吳起回答說：「關於嚴明刑賞的事，臣無法詳細盡述。雖然如此，這並不是可以完全依靠的。凡是發號施令而人們樂於聽從，興師動眾而人們樂於參戰，短兵相接而人們樂於赴死。這三條，才是君主所應當真正依靠的。」","analysis":"【主題與背景】\\\\n本段深刻批判了單靠「嚴刑明賞」的外在威逼激勵，提出軍事動員的最高境界——「三樂」（樂聞、樂戰、樂死）。\\\\n\\\\n【詞義與名物】\\\\n「三樂」：發號布令樂聞、興師動眾樂戰、交兵接刃樂死。「非所恃也」：單靠刑賞不足以激發軍隊最高戰鬥力。\\\\n\\\\n【兵家戰略】\\\\n吳起超越了單純法家的刑賞觀念，指出軍隊真正的戰鬥力來源於士兵內心的認同與主動願望（樂）。唯有建立起這種內在動機，部隊才能在生死考驗面前堅不可摧。"}},{"id":"wu-zi_ch-6_p-2","chapterId":"wu-zi_ch-6","order":2,"canonicalText":"武侯曰：「致之奈何？」對曰：「君舉有功而進饗之，無功而勵之。」","sentenceIds":["wu-zi_ch-6_p-2_s-1","wu-zi_ch-6_p-2_s-2","wu-zi_ch-6_p-2_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"魏武侯問：「怎樣才能做到這樣呢？」吳起回答說：「主君如果能推舉有功的人並進獻宴饗酬勞他們，對沒有功勞的人也進行鼓勵關懷。」","analysis":"【主題與背景】\\\\n本段論述實現士兵主動效命（致之）的具體宴饗與獎勵機制。\\\\n\\\\n【詞義與名物】\\\\n「饗」：在宗廟廷堂舉行尊榮宴饗。「有功饗之，無功勵之」：既獎勵立功者，又關懷鼓勵未立功者。\\\\n\\\\n【兵家戰略】\\\\n吳起主張正向激勵與全員覆蓋。賞賜不僅是物質給予，更是政治榮譽；同時對暫未立功者給予鼓勵，維護軍心士氣的普遍高昂。"}},{"id":"wu-zi_ch-6_p-3","chapterId":"wu-zi_ch-6","order":3,"canonicalText":"於是武侯設坐廟廷為三行饗士大夫。上功坐前行，餚席兼重器、上牢。次功坐中行，餚席器差減。無功坐後行，餚席無重器。饗畢而出，又頒賜有功者父母妻子於廟門外，亦以功為差。有死事之家，歲被使者勞賜其父母，著不忘於心。行之三年，秦人興師，臨於西河，魏士聞之，不待吏令，介冑而奮擊之者以萬數。","sentenceIds":["wu-zi_ch-6_p-3_s-1","wu-zi_ch-6_p-3_s-2","wu-zi_ch-6_p-3_s-3","wu-zi_ch-6_p-3_s-4","wu-zi_ch-6_p-3_s-5","wu-zi_ch-6_p-3_s-6","wu-zi_ch-6_p-3_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"於是魏武侯在宗廟廷堂設座，分為三行宴饗士大夫官兵。立上等功者坐在前行，酒席配備貴重禮器與上等牛羊祭品；立次等功者坐在中行，酒席禮器稍有減少；無功者坐在後行，酒席不設貴重禮器。宴饗結束出來後，又在宗廟門外頒發賞賜給有功者的父母妻兒，也按功勞區分等級。對陣亡將士的家庭，每年派使者慰問賞賜其父母，表明君主銘記於心。施行了三年，秦國興師動眾進犯西河地區，魏國士兵聽到消息，不等待官吏命令，穿戴鎧甲頭盔奮勇上前打擊敵人的數以萬計。","analysis":"【主題與背景】\\\\n本段記載魏國實施尊榮宴饗、惠及家屬、優撫陣亡將士家族的具體制度，以及這一制度產生的巨大動員效果。\\\\n\\\\n【詞義與名物】\\\\n「三行饗士」：前行（上功）、中行（次功）、後行（無功）的層次榮譽宴饗。「優撫死事之家」：國家每年慰問陣亡將士父母。\\\\n\\\\n【兵家戰略】\\\\n吳起創建了古代最完備的軍功榮譽與社會保障制度。將榮譽延伸至家族妻子，並由國家提供長遠優撫，極大地消除了士兵的後顧之憂，形成了「不待吏令，介冑奮擊」的驚人戰鬥力。"}},{"id":"wu-zi_ch-6_p-4","chapterId":"wu-zi_ch-6","order":4,"canonicalText":"武侯召吳起而謂曰：「子前日之教行矣。」起對曰：「臣聞人有短長，氣有盛衰。君試發無功者五萬人，臣請率以當之。脫其不勝，取笑於諸侯，失權於天下矣。今使一死賊伏於曠野，千人追之，莫不梟視狼顧。何者？忌其暴起而害己。是以一人投命，足懼千夫。今臣以五萬之眾，而為一死賊，率以討之，固難敵矣。」","sentenceIds":["wu-zi_ch-6_p-4_s-1","wu-zi_ch-6_p-4_s-2","wu-zi_ch-6_p-4_s-3","wu-zi_ch-6_p-4_s-4","wu-zi_ch-6_p-4_s-5","wu-zi_ch-6_p-4_s-6","wu-zi_ch-6_p-4_s-7","wu-zi_ch-6_p-4_s-8","wu-zi_ch-6_p-4_s-9","wu-zi_ch-6_p-4_s-10"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"魏武侯召見吳起並對他說：「您前些日子的教化已經見效了。」吳起回答說：「臣聽說人有短處長處，士氣有盛大衰微。主君試著調發未立功的士兵五萬人，臣請求率領他們去抵擋秦軍。如果不能獲勝，願在諸侯面前受取笑，在天下喪失聲威。如今假使有一個抱定必死決心的亡命之徒潛伏在曠野中，上千人去追捕他，沒有人不警惕顧盼恐懼。為什麼呢？害怕他突然奮起傷害自己。因此一個人敢於豁出性命，就足以讓千人感到恐懼。如今臣帶著五萬大眾，使他們人人成為必死之士，率領他們去討伐敵人，敵人自然難以抵擋了。」","analysis":"【主題與背景】\\\\n本段論述「一死賊伏於曠野，千人追之」的心理威懾效應，說明如何將未立功者激發為必死之士。\\\\n\\\\n【詞義與名物】\\\\n「梟視狼顧」：形容警惕恐懼、四處顧盼不敢逼近的心理狀態。「一人投命，足懼千夫」：敢於捨命者產生的強大心理威懾。\\\\n\\\\n【兵家戰略】\\\\n吳起揭示了軍事心理學的深刻法則。未立功的士兵渴望證明自己與獲得榮譽，只要給予機會並激發其必死決心，五萬「求功必死之士」就能產生摧枯拉朽的戰術威力。"}},{"id":"wu-zi_ch-6_p-5","chapterId":"wu-zi_ch-6","order":5,"canonicalText":"於是武侯從之，兼車五百乘，騎三千匹，而破秦五十萬眾，此勵士之功也。","sentenceIds":["wu-zi_ch-6_p-5_s-1"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"於是魏武侯聽從了他的建議，派戰車五百乘、騎兵三千匹，配屬吳起率領五萬精兵，結果大敗秦軍五十萬大軍，這就是勵士激勵士卒產生的巨大功績。","analysis":"【主題與背景】\\\\n本段記錄了戰國歷史上以少勝多的經典戰役——陰晉之戰，吳起以五萬魏武卒大破五十萬秦軍。\\\\n\\\\n【詞義與名物】\\\\n「陰晉之戰」：西元前389年魏國吳起以五萬大軍擊敗秦軍五十萬的輝煌戰役。\\\\n\\\\n【兵家戰略】\\\\n本段是《吳子兵法》全書的總結。五萬經過嚴格訓練、深受榮譽感激勵且無後顧之憂的精銳部隊，在優質車騎配合下，擊敗了十倍於己的敵人，證明瞭政治教化與軍事勵士的至高威力。"}},{"id":"wu-zi_ch-6_p-6","chapterId":"wu-zi_ch-6","order":6,"canonicalText":"先戰一日，吳起令三軍曰：「諸吏士當從受馳。車騎與徒，若車不得車，騎不得騎，徒不得徒，雖破軍皆無易。」故戰之日，其令不煩而威震天下。","sentenceIds":["wu-zi_ch-6_p-6_s-1","wu-zi_ch-6_p-6_s-2","wu-zi_ch-6_p-6_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wu-zi/zh"}],"readingAid":{"translation":"開戰的前一天，吳起向三軍下達軍令說：「各位官兵應當跟從指揮受命馳騁。無論戰車、騎兵還是步兵，如果戰車未能擊毀敵車，騎兵未能擊毀敵騎，步兵未能擊毀敵步兵，即使打勝仗也沒有任何賞賜。」所以開戰的那一天，他的軍令並不煩瑣卻威震天下。","analysis":"【主題與背景】\\\\n本段記載決戰前夕吳起下達的極致目標責任制軍令（對位擊破），體現了嚴明高效的戰術執行力。\\\\n\\\\n【詞義與名物】\\\\n「無易」：沒有賞賜、不予獎勵。「其令不煩」：軍令簡明扼要、目標極度明確。\\\\n\\\\n【兵家戰略】\\\\n吳起在決戰前夕將戰鬥目標極化與具體化（車對車、騎對騎、步對步），使每個兵種每個個體都有極其清晰的職責目標。軍令簡潔明確，卻展現出無可匹敵的威懾力與戰鬥執行力。"}}],"sentences":[{"id":"wu-zi_ch-1_p-1_s-1","passageId":"wu-zi_ch-1_p-1","order":1,"canonicalText":"吳起儒服以兵機見魏文侯。","chunks":[["吳起儒服以兵機見魏文侯。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-1_s-2","passageId":"wu-zi_ch-1_p-1","order":2,"canonicalText":"文侯曰：「寡人不好軍旅之事。","chunks":[["文侯曰：「寡人不好軍旅之事。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-1_s-3","passageId":"wu-zi_ch-1_p-1","order":3,"canonicalText":"」起曰：「臣以見占隱，以往察來，主君何言與心違？","chunks":[["」起曰：「臣以見占隱，以往察來，主君何言與心違？","zh-Hant"]]},{"id":"wu-zi_ch-1_p-1_s-4","passageId":"wu-zi_ch-1_p-1","order":4,"canonicalText":"今君四時使斬離皮革，掩以朱漆，畫以丹青，爍以犀象。","chunks":[["今君四時使斬離皮革，掩以朱漆，畫以丹青，爍以犀象。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-1_s-5","passageId":"wu-zi_ch-1_p-1","order":5,"canonicalText":"冬日衣之則不溫，夏日衣之則不涼。","chunks":[["冬日衣之則不溫，夏日衣之則不涼。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-1_s-6","passageId":"wu-zi_ch-1_p-1","order":6,"canonicalText":"為長戟二丈四尺，短戟一丈二尺。","chunks":[["為長戟二丈四尺，短戟一丈二尺。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-1_s-7","passageId":"wu-zi_ch-1_p-1","order":7,"canonicalText":"革車奄戶，縵輪籠轂，觀之於目則不麗，乘之以田則不輕，不識主君安用此也？","chunks":[["革車奄戶，縵輪籠轂，觀之於目則不麗，乘之以田則不輕，不識主君安用此也？","zh-Hant"]]},{"id":"wu-zi_ch-1_p-1_s-8","passageId":"wu-zi_ch-1_p-1","order":8,"canonicalText":"若以備進戰退守，而不求能用者，譬猶伏雞之搏狸，乳犬之犯虎，雖有鬥心，隨之死矣。","chunks":[["若以備進戰退守，而不求能用者，譬猶伏雞之搏狸，乳犬之犯虎，雖有鬥心，隨之死矣。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-1_s-9","passageId":"wu-zi_ch-1_p-1","order":9,"canonicalText":"昔承桑氏之君，修德廢武，以滅其國。","chunks":[["昔承桑氏之君，修德廢武，以滅其國。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-1_s-10","passageId":"wu-zi_ch-1_p-1","order":10,"canonicalText":"有扈氏之君，恃眾好勇，以喪其社稷。","chunks":[["有扈氏之君，恃眾好勇，以喪其社稷。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-1_s-11","passageId":"wu-zi_ch-1_p-1","order":11,"canonicalText":"明主鑒茲，必內修文德，外治武備。","chunks":[["明主鑒茲，必內修文德，外治武備。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-1_s-12","passageId":"wu-zi_ch-1_p-1","order":12,"canonicalText":"故當敵而不進，無逮於義矣；","chunks":[["故當敵而不進，無逮於義矣；","zh-Hant"]]},{"id":"wu-zi_ch-1_p-1_s-13","passageId":"wu-zi_ch-1_p-1","order":13,"canonicalText":"僵屍而哀之，無逮於仁矣。","chunks":[["僵屍而哀之，無逮於仁矣。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-1_s-14","passageId":"wu-zi_ch-1_p-1","order":14,"canonicalText":"」於是文侯身自布席，夫人捧觴，醮吳起於廟，立為大將，守西河。","chunks":[["」於是文侯身自布席，夫人捧觴，醮吳起於廟，立為大將，守西河。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-1_s-15","passageId":"wu-zi_ch-1_p-1","order":15,"canonicalText":"與諸侯大戰七十六，全勝六十四，餘則鈞解。","chunks":[["與諸侯大戰七十六，全勝六十四，餘則鈞解。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-1_s-16","passageId":"wu-zi_ch-1_p-1","order":16,"canonicalText":"闢土四面，拓地千里，皆起之功也。","chunks":[["闢土四面，拓地千里，皆起之功也。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-2_s-1","passageId":"wu-zi_ch-1_p-2","order":1,"canonicalText":"吳子曰：「昔之圖國家者，必先教百姓而親萬民。","chunks":[["吳子曰：「昔之圖國家者，必先教百姓而親萬民。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-2_s-2","passageId":"wu-zi_ch-1_p-2","order":2,"canonicalText":"有四不和：不和於國，不可以出軍；","chunks":[["有四不和：不和於國，不可以出軍；","zh-Hant"]]},{"id":"wu-zi_ch-1_p-2_s-3","passageId":"wu-zi_ch-1_p-2","order":3,"canonicalText":"不和於軍，不可以出陳；","chunks":[["不和於軍，不可以出陳；","zh-Hant"]]},{"id":"wu-zi_ch-1_p-2_s-4","passageId":"wu-zi_ch-1_p-2","order":4,"canonicalText":"不和於陳，不可以進戰；","chunks":[["不和於陳，不可以進戰；","zh-Hant"]]},{"id":"wu-zi_ch-1_p-2_s-5","passageId":"wu-zi_ch-1_p-2","order":5,"canonicalText":"不和於戰，不可以決勝。","chunks":[["不和於戰，不可以決勝。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-2_s-6","passageId":"wu-zi_ch-1_p-2","order":6,"canonicalText":"是以有道之主，將用其民，先和而造大事。","chunks":[["是以有道之主，將用其民，先和而造大事。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-2_s-7","passageId":"wu-zi_ch-1_p-2","order":7,"canonicalText":"不敢信其私謀，必告於祖廟，啟於元龜，參之天時，吉乃後舉。","chunks":[["不敢信其私謀，必告於祖廟，啟於元龜，參之天時，吉乃後舉。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-2_s-8","passageId":"wu-zi_ch-1_p-2","order":8,"canonicalText":"民知君之愛其命，惜其死，若此之至，而與之臨難，則士以盡死為榮，退生為辱矣。","chunks":[["民知君之愛其命，惜其死，若此之至，而與之臨難，則士以盡死為榮，退生為辱矣。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-2_s-9","passageId":"wu-zi_ch-1_p-2","order":9,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-1_p-3_s-1","passageId":"wu-zi_ch-1_p-3","order":1,"canonicalText":"吳子曰：「夫道者，所以反本復始。","chunks":[["吳子曰：「夫道者，所以反本復始。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-3_s-2","passageId":"wu-zi_ch-1_p-3","order":2,"canonicalText":"義者，所以行事立功。","chunks":[["義者，所以行事立功。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-3_s-3","passageId":"wu-zi_ch-1_p-3","order":3,"canonicalText":"謀者，所以違害就利。","chunks":[["謀者，所以違害就利。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-3_s-4","passageId":"wu-zi_ch-1_p-3","order":4,"canonicalText":"要者，所以保業守成。","chunks":[["要者，所以保業守成。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-3_s-5","passageId":"wu-zi_ch-1_p-3","order":5,"canonicalText":"若行不合道，舉不合義，而處大居貴，患必及之。","chunks":[["若行不合道，舉不合義，而處大居貴，患必及之。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-3_s-6","passageId":"wu-zi_ch-1_p-3","order":6,"canonicalText":"是以聖人綏之以道，理之以義，動之以禮，撫之以仁。","chunks":[["是以聖人綏之以道，理之以義，動之以禮，撫之以仁。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-3_s-7","passageId":"wu-zi_ch-1_p-3","order":7,"canonicalText":"此四德者，修之則興，廢之則衰。","chunks":[["此四德者，修之則興，廢之則衰。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-3_s-8","passageId":"wu-zi_ch-1_p-3","order":8,"canonicalText":"故成湯討桀而夏民喜悅，周武伐紂而殷人不非。","chunks":[["故成湯討桀而夏民喜悅，周武伐紂而殷人不非。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-3_s-9","passageId":"wu-zi_ch-1_p-3","order":9,"canonicalText":"舉順天人，故能然矣。","chunks":[["舉順天人，故能然矣。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-3_s-10","passageId":"wu-zi_ch-1_p-3","order":10,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-1_p-4_s-1","passageId":"wu-zi_ch-1_p-4","order":1,"canonicalText":"吳子曰：「凡制國治軍，必教之以禮，勵之以義，使有恥也。","chunks":[["吳子曰：「凡制國治軍，必教之以禮，勵之以義，使有恥也。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-4_s-2","passageId":"wu-zi_ch-1_p-4","order":2,"canonicalText":"夫人有恥，在大足以戰，在小足以守矣。","chunks":[["夫人有恥，在大足以戰，在小足以守矣。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-4_s-3","passageId":"wu-zi_ch-1_p-4","order":3,"canonicalText":"然戰勝易，守勝難。","chunks":[["然戰勝易，守勝難。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-4_s-4","passageId":"wu-zi_ch-1_p-4","order":4,"canonicalText":"故曰：天下戰國，五勝者禍，四勝者弊，三勝者霸，二勝者王，一勝者帝。","chunks":[["故曰：天下戰國，五勝者禍，四勝者弊，三勝者霸，二勝者王，一勝者帝。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-4_s-5","passageId":"wu-zi_ch-1_p-4","order":5,"canonicalText":"是以數勝得天下者稀，以亡者眾。","chunks":[["是以數勝得天下者稀，以亡者眾。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-4_s-6","passageId":"wu-zi_ch-1_p-4","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-1_p-5_s-1","passageId":"wu-zi_ch-1_p-5","order":1,"canonicalText":"吳子曰：「凡兵之所起者有五：一曰爭名，二曰爭利，三曰積德惡，四曰內亂，五曰因饑。","chunks":[["吳子曰：「凡兵之所起者有五：一曰爭名，二曰爭利，三曰積德惡，四曰內亂，五曰因饑。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-5_s-2","passageId":"wu-zi_ch-1_p-5","order":2,"canonicalText":"其名又有五：一曰義兵，二曰彊兵，三曰剛兵，四曰暴兵，五曰逆兵。","chunks":[["其名又有五：一曰義兵，二曰彊兵，三曰剛兵，四曰暴兵，五曰逆兵。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-5_s-3","passageId":"wu-zi_ch-1_p-5","order":3,"canonicalText":"禁暴救亂曰義，恃眾以伐曰彊，因怒興師曰剛，棄禮貪利曰暴，國亂人疲舉事動眾曰逆。","chunks":[["禁暴救亂曰義，恃眾以伐曰彊，因怒興師曰剛，棄禮貪利曰暴，國亂人疲舉事動眾曰逆。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-5_s-4","passageId":"wu-zi_ch-1_p-5","order":4,"canonicalText":"五者之數，各有其道，義必以禮服，彊必以謙服，剛必以辭服，暴必以詐服，逆必以權服。","chunks":[["五者之數，各有其道，義必以禮服，彊必以謙服，剛必以辭服，暴必以詐服，逆必以權服。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-5_s-5","passageId":"wu-zi_ch-1_p-5","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-1_p-6_s-1","passageId":"wu-zi_ch-1_p-6","order":1,"canonicalText":"武侯問曰：「願聞治兵、料人、固國之道。","chunks":[["武侯問曰：「願聞治兵、料人、固國之道。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-6_s-2","passageId":"wu-zi_ch-1_p-6","order":2,"canonicalText":"」起對曰：「古之明王，必謹君臣之禮，飾上下之儀，安集吏民，順俗而教，簡募良材，以備不虞。","chunks":[["」起對曰：「古之明王，必謹君臣之禮，飾上下之儀，安集吏民，順俗而教，簡募良材，以備不虞。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-6_s-3","passageId":"wu-zi_ch-1_p-6","order":3,"canonicalText":"昔齊桓募士五萬，以霸諸侯。","chunks":[["昔齊桓募士五萬，以霸諸侯。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-6_s-4","passageId":"wu-zi_ch-1_p-6","order":4,"canonicalText":"晉文召為前行四萬，以獲其志。","chunks":[["晉文召為前行四萬，以獲其志。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-6_s-5","passageId":"wu-zi_ch-1_p-6","order":5,"canonicalText":"秦繆置陷陳三萬，以服鄰敵。","chunks":[["秦繆置陷陳三萬，以服鄰敵。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-6_s-6","passageId":"wu-zi_ch-1_p-6","order":6,"canonicalText":"故強國之君，必料其民。","chunks":[["故強國之君，必料其民。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-6_s-7","passageId":"wu-zi_ch-1_p-6","order":7,"canonicalText":"民有膽勇氣力者，聚為一卒。","chunks":[["民有膽勇氣力者，聚為一卒。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-6_s-8","passageId":"wu-zi_ch-1_p-6","order":8,"canonicalText":"樂以進戰效力、以顯其忠勇者，聚為一卒。","chunks":[["樂以進戰效力、以顯其忠勇者，聚為一卒。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-6_s-9","passageId":"wu-zi_ch-1_p-6","order":9,"canonicalText":"能踰高超遠、輕足善走者，聚為一卒。","chunks":[["能踰高超遠、輕足善走者，聚為一卒。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-6_s-10","passageId":"wu-zi_ch-1_p-6","order":10,"canonicalText":"王臣失位而欲見功於上者，聚為一卒。","chunks":[["王臣失位而欲見功於上者，聚為一卒。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-6_s-11","passageId":"wu-zi_ch-1_p-6","order":11,"canonicalText":"棄城去守、欲除其醜者，聚為一卒。","chunks":[["棄城去守、欲除其醜者，聚為一卒。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-6_s-12","passageId":"wu-zi_ch-1_p-6","order":12,"canonicalText":"此五者，軍之練銳也。","chunks":[["此五者，軍之練銳也。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-6_s-13","passageId":"wu-zi_ch-1_p-6","order":13,"canonicalText":"有此三千人，內出可以決圍，外入可以屠城矣。","chunks":[["有此三千人，內出可以決圍，外入可以屠城矣。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-6_s-14","passageId":"wu-zi_ch-1_p-6","order":14,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-1_p-7_s-1","passageId":"wu-zi_ch-1_p-7","order":1,"canonicalText":"武侯問曰：「願聞陳必定、守必固、戰必勝之道。","chunks":[["武侯問曰：「願聞陳必定、守必固、戰必勝之道。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-7_s-2","passageId":"wu-zi_ch-1_p-7","order":2,"canonicalText":"」起對曰：「立見且可，豈直聞乎！","chunks":[["」起對曰：「立見且可，豈直聞乎！","zh-Hant"]]},{"id":"wu-zi_ch-1_p-7_s-3","passageId":"wu-zi_ch-1_p-7","order":3,"canonicalText":"君能使賢者居上，不肖者處下，則陳已定矣。","chunks":[["君能使賢者居上，不肖者處下，則陳已定矣。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-7_s-4","passageId":"wu-zi_ch-1_p-7","order":4,"canonicalText":"民安其田宅，親其有司，則守已固矣。","chunks":[["民安其田宅，親其有司，則守已固矣。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-7_s-5","passageId":"wu-zi_ch-1_p-7","order":5,"canonicalText":"百姓皆是吾君而非鄰國，則戰已勝矣。","chunks":[["百姓皆是吾君而非鄰國，則戰已勝矣。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-7_s-6","passageId":"wu-zi_ch-1_p-7","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-1_p-8_s-1","passageId":"wu-zi_ch-1_p-8","order":1,"canonicalText":"武侯嘗謀事，群臣莫能及，罷朝而有喜色。","chunks":[["武侯嘗謀事，群臣莫能及，罷朝而有喜色。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-8_s-2","passageId":"wu-zi_ch-1_p-8","order":2,"canonicalText":"起進曰：「昔楚莊王嘗謀事，群臣莫能及，退朝而有憂色。","chunks":[["起進曰：「昔楚莊王嘗謀事，群臣莫能及，退朝而有憂色。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-8_s-3","passageId":"wu-zi_ch-1_p-8","order":3,"canonicalText":"申公問曰：『君有憂色，何也？","chunks":[["申公問曰：『君有憂色，何也？","zh-Hant"]]},{"id":"wu-zi_ch-1_p-8_s-4","passageId":"wu-zi_ch-1_p-8","order":4,"canonicalText":"』曰：『寡人聞之，世不絕聖，國不乏賢，能得其師者王，得其友者霸。","chunks":[["』曰：『寡人聞之，世不絕聖，國不乏賢，能得其師者王，得其友者霸。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-8_s-5","passageId":"wu-zi_ch-1_p-8","order":5,"canonicalText":"今寡人不才，而群臣莫及者，楚國其殆矣。","chunks":[["今寡人不才，而群臣莫及者，楚國其殆矣。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-8_s-6","passageId":"wu-zi_ch-1_p-8","order":6,"canonicalText":"』此楚莊王之所憂，而君說之，臣竊懼矣。","chunks":[["』此楚莊王之所憂，而君說之，臣竊懼矣。","zh-Hant"]]},{"id":"wu-zi_ch-1_p-8_s-7","passageId":"wu-zi_ch-1_p-8","order":7,"canonicalText":"」於是武侯有慚色。","chunks":[["」於是武侯有慚色。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-1","passageId":"wu-zi_ch-2_p-1","order":1,"canonicalText":"武侯謂吳起曰：「今秦脅吾西，楚帶吾南，趙衝吾北，齊臨吾東，燕絕吾後，韓據吾前。","chunks":[["武侯謂吳起曰：「今秦脅吾西，楚帶吾南，趙衝吾北，齊臨吾東，燕絕吾後，韓據吾前。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-2","passageId":"wu-zi_ch-2_p-1","order":2,"canonicalText":"六國兵四守，勢甚不便，憂此奈何？","chunks":[["六國兵四守，勢甚不便，憂此奈何？","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-3","passageId":"wu-zi_ch-2_p-1","order":3,"canonicalText":"」起對曰：「夫安國家之道，先戒為寶。","chunks":[["」起對曰：「夫安國家之道，先戒為寶。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-4","passageId":"wu-zi_ch-2_p-1","order":4,"canonicalText":"今君已戒，禍其遠矣。","chunks":[["今君已戒，禍其遠矣。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-5","passageId":"wu-zi_ch-2_p-1","order":5,"canonicalText":"臣請論六國之俗：夫齊陳重而不堅，秦陳散而自鬭，楚陳整而不久，燕陳守而不走，三晉陳治而不用。","chunks":[["臣請論六國之俗：夫齊陳重而不堅，秦陳散而自鬭，楚陳整而不久，燕陳守而不走，三晉陳治而不用。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-6","passageId":"wu-zi_ch-2_p-1","order":6,"canonicalText":"夫齊性剛，其國富，君臣驕奢而簡於細民，其政寬而祿不均，一陳兩心，前重後輕，故重而不堅。","chunks":[["夫齊性剛，其國富，君臣驕奢而簡於細民，其政寬而祿不均，一陳兩心，前重後輕，故重而不堅。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-7","passageId":"wu-zi_ch-2_p-1","order":7,"canonicalText":"擊此之道，必三分之，獵其左右，脅而從之，其陳可壞。","chunks":[["擊此之道，必三分之，獵其左右，脅而從之，其陳可壞。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-8","passageId":"wu-zi_ch-2_p-1","order":8,"canonicalText":"秦性強，其地險，其政嚴，其賞罰信，其人不讓，皆有鬭心，故散而自戰。","chunks":[["秦性強，其地險，其政嚴，其賞罰信，其人不讓，皆有鬭心，故散而自戰。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-9","passageId":"wu-zi_ch-2_p-1","order":9,"canonicalText":"擊此之道，必先示之以利而引去之，士貪於得而離其將，乘乖獵散，設伏投機，其將可取。","chunks":[["擊此之道，必先示之以利而引去之，士貪於得而離其將，乘乖獵散，設伏投機，其將可取。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-10","passageId":"wu-zi_ch-2_p-1","order":10,"canonicalText":"楚性弱，其地廣，其政騷，其民疲，故整而不久。","chunks":[["楚性弱，其地廣，其政騷，其民疲，故整而不久。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-11","passageId":"wu-zi_ch-2_p-1","order":11,"canonicalText":"擊此之道，襲亂其屯，先奪其氣。","chunks":[["擊此之道，襲亂其屯，先奪其氣。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-12","passageId":"wu-zi_ch-2_p-1","order":12,"canonicalText":"輕進速退，弊而勞之，勿與戰爭，其軍可敗。","chunks":[["輕進速退，弊而勞之，勿與戰爭，其軍可敗。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-13","passageId":"wu-zi_ch-2_p-1","order":13,"canonicalText":"燕性愨，其民慎，好勇義，寡詐謀，故守而不走。","chunks":[["燕性愨，其民慎，好勇義，寡詐謀，故守而不走。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-14","passageId":"wu-zi_ch-2_p-1","order":14,"canonicalText":"擊此之道，觸而迫之，陵而遠之，馳而後之，則上疑而下懼，謹我車騎必避之路，其將可虜。","chunks":[["擊此之道，觸而迫之，陵而遠之，馳而後之，則上疑而下懼，謹我車騎必避之路，其將可虜。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-15","passageId":"wu-zi_ch-2_p-1","order":15,"canonicalText":"三晉者，中國也，其性和，其政平，其民疲於戰，習於兵，輕其將，薄其祿，士無死志，故治而不用。","chunks":[["三晉者，中國也，其性和，其政平，其民疲於戰，習於兵，輕其將，薄其祿，士無死志，故治而不用。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-16","passageId":"wu-zi_ch-2_p-1","order":16,"canonicalText":"擊此之道，阻陳而壓之，眾來則拒之，去則追之，以倦其師。","chunks":[["擊此之道，阻陳而壓之，眾來則拒之，去則追之，以倦其師。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-17","passageId":"wu-zi_ch-2_p-1","order":17,"canonicalText":"此其勢也。","chunks":[["此其勢也。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-18","passageId":"wu-zi_ch-2_p-1","order":18,"canonicalText":"然則一軍之中，必有虎賁之士；","chunks":[["然則一軍之中，必有虎賁之士；","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-19","passageId":"wu-zi_ch-2_p-1","order":19,"canonicalText":"力輕扛鼎，足輕戎馬，搴旗斬將，必有能者。","chunks":[["力輕扛鼎，足輕戎馬，搴旗斬將，必有能者。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-20","passageId":"wu-zi_ch-2_p-1","order":20,"canonicalText":"若此之等，選而別之，愛而貴之，是謂軍命。","chunks":[["若此之等，選而別之，愛而貴之，是謂軍命。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-21","passageId":"wu-zi_ch-2_p-1","order":21,"canonicalText":"其有工用五兵、材力健疾、志在吞敵者，必加其爵列，可以決勝。","chunks":[["其有工用五兵、材力健疾、志在吞敵者，必加其爵列，可以決勝。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-22","passageId":"wu-zi_ch-2_p-1","order":22,"canonicalText":"厚其父母妻子，勸賞畏罰，此堅陳之士，可與持久。","chunks":[["厚其父母妻子，勸賞畏罰，此堅陳之士，可與持久。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-23","passageId":"wu-zi_ch-2_p-1","order":23,"canonicalText":"能審料此，可以擊倍。","chunks":[["能審料此，可以擊倍。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-24","passageId":"wu-zi_ch-2_p-1","order":24,"canonicalText":"」武侯曰：「善。","chunks":[["」武侯曰：「善。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-1_s-25","passageId":"wu-zi_ch-2_p-1","order":25,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-2_p-2_s-1","passageId":"wu-zi_ch-2_p-2","order":1,"canonicalText":"吳子曰：「凡料敵有不卜而與之戰者八：一曰疾風大寒，早興寤遷，刊木濟水，不憚艱難；","chunks":[["吳子曰：「凡料敵有不卜而與之戰者八：一曰疾風大寒，早興寤遷，刊木濟水，不憚艱難；","zh-Hant"]]},{"id":"wu-zi_ch-2_p-2_s-2","passageId":"wu-zi_ch-2_p-2","order":2,"canonicalText":"二曰盛夏炎熱，晏興無間，行驅飢渴，務於取遠；","chunks":[["二曰盛夏炎熱，晏興無間，行驅飢渴，務於取遠；","zh-Hant"]]},{"id":"wu-zi_ch-2_p-2_s-3","passageId":"wu-zi_ch-2_p-2","order":3,"canonicalText":"三曰師既淹久，糧食無有，百姓怨怒，祅祥數起，上不能止；","chunks":[["三曰師既淹久，糧食無有，百姓怨怒，祅祥數起，上不能止；","zh-Hant"]]},{"id":"wu-zi_ch-2_p-2_s-4","passageId":"wu-zi_ch-2_p-2","order":4,"canonicalText":"四曰軍資既竭，薪芻既寡，天多陰雨，欲掠無所；","chunks":[["四曰軍資既竭，薪芻既寡，天多陰雨，欲掠無所；","zh-Hant"]]},{"id":"wu-zi_ch-2_p-2_s-5","passageId":"wu-zi_ch-2_p-2","order":5,"canonicalText":"五曰徒眾不多，水地不利，人馬疾疫，四鄰不至；","chunks":[["五曰徒眾不多，水地不利，人馬疾疫，四鄰不至；","zh-Hant"]]},{"id":"wu-zi_ch-2_p-2_s-6","passageId":"wu-zi_ch-2_p-2","order":6,"canonicalText":"六曰道遠日暮，士眾勞懼，倦而未食，解甲而息；","chunks":[["六曰道遠日暮，士眾勞懼，倦而未食，解甲而息；","zh-Hant"]]},{"id":"wu-zi_ch-2_p-2_s-7","passageId":"wu-zi_ch-2_p-2","order":7,"canonicalText":"七曰將薄吏輕，士卒不固，三軍數驚，師徒無助；","chunks":[["七曰將薄吏輕，士卒不固，三軍數驚，師徒無助；","zh-Hant"]]},{"id":"wu-zi_ch-2_p-2_s-8","passageId":"wu-zi_ch-2_p-2","order":8,"canonicalText":"八曰陳而未定，舍而未畢，行阪涉險，半隱半出。","chunks":[["八曰陳而未定，舍而未畢，行阪涉險，半隱半出。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-2_s-9","passageId":"wu-zi_ch-2_p-2","order":9,"canonicalText":"諸如此者，擊之勿疑。","chunks":[["諸如此者，擊之勿疑。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-2_s-10","passageId":"wu-zi_ch-2_p-2","order":10,"canonicalText":"有不占而避之者六：一曰土地廣大，人民富眾；","chunks":[["有不占而避之者六：一曰土地廣大，人民富眾；","zh-Hant"]]},{"id":"wu-zi_ch-2_p-2_s-11","passageId":"wu-zi_ch-2_p-2","order":11,"canonicalText":"二曰上愛其下，惠施流布；","chunks":[["二曰上愛其下，惠施流布；","zh-Hant"]]},{"id":"wu-zi_ch-2_p-2_s-12","passageId":"wu-zi_ch-2_p-2","order":12,"canonicalText":"三曰賞信刑察，發必得時；","chunks":[["三曰賞信刑察，發必得時；","zh-Hant"]]},{"id":"wu-zi_ch-2_p-2_s-13","passageId":"wu-zi_ch-2_p-2","order":13,"canonicalText":"四曰陳功居列，任賢使能；","chunks":[["四曰陳功居列，任賢使能；","zh-Hant"]]},{"id":"wu-zi_ch-2_p-2_s-14","passageId":"wu-zi_ch-2_p-2","order":14,"canonicalText":"五曰師徒之眾，兵甲之精；","chunks":[["五曰師徒之眾，兵甲之精；","zh-Hant"]]},{"id":"wu-zi_ch-2_p-2_s-15","passageId":"wu-zi_ch-2_p-2","order":15,"canonicalText":"六曰四鄰之助，大國之援。","chunks":[["六曰四鄰之助，大國之援。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-2_s-16","passageId":"wu-zi_ch-2_p-2","order":16,"canonicalText":"凡此不如敵人，避之勿疑。","chunks":[["凡此不如敵人，避之勿疑。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-2_s-17","passageId":"wu-zi_ch-2_p-2","order":17,"canonicalText":"所謂見可而進，知難而退也。","chunks":[["所謂見可而進，知難而退也。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-2_s-18","passageId":"wu-zi_ch-2_p-2","order":18,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-2_p-3_s-1","passageId":"wu-zi_ch-2_p-3","order":1,"canonicalText":"武侯問曰：「吾欲觀敵之外以知其內，察其進以知其止，以定勝負，可得聞乎？","chunks":[["武侯問曰：「吾欲觀敵之外以知其內，察其進以知其止，以定勝負，可得聞乎？","zh-Hant"]]},{"id":"wu-zi_ch-2_p-3_s-2","passageId":"wu-zi_ch-2_p-3","order":2,"canonicalText":"」起對曰：「敵人之來，蕩蕩無慮，旌旗煩亂，人馬數顧，一可擊十，必使無措。","chunks":[["」起對曰：「敵人之來，蕩蕩無慮，旌旗煩亂，人馬數顧，一可擊十，必使無措。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-3_s-3","passageId":"wu-zi_ch-2_p-3","order":3,"canonicalText":"諸侯大會，君臣未和，溝壘未成，禁令未施，三軍匈匈，欲前不能，欲去不敢，以半擊倍，百戰不殆。","chunks":[["諸侯大會，君臣未和，溝壘未成，禁令未施，三軍匈匈，欲前不能，欲去不敢，以半擊倍，百戰不殆。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-3_s-4","passageId":"wu-zi_ch-2_p-3","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-2_p-4_s-1","passageId":"wu-zi_ch-2_p-4","order":1,"canonicalText":"武侯問敵必可擊之道。","chunks":[["武侯問敵必可擊之道。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-4_s-2","passageId":"wu-zi_ch-2_p-4","order":2,"canonicalText":"起對曰：「用兵必須審敵虛實而趨其危。","chunks":[["起對曰：「用兵必須審敵虛實而趨其危。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-4_s-3","passageId":"wu-zi_ch-2_p-4","order":3,"canonicalText":"敵人遠來新至、行列未定可擊，既食未設備可擊，奔走可擊，勤勞可擊，未得地利可擊，失時不從可擊，旌旗亂動可擊，涉長道後行未息可擊，涉水半渡可擊，險道狹路可擊，陳數移動可擊，將離士卒可擊，心怖可擊。","chunks":[["敵人遠來新至、行列未定可擊，既食未設備可擊，奔走可擊，勤勞可擊，未得地利可擊，失時不從可擊，旌旗亂動可擊，涉長道後行未息可擊，涉水半渡可擊，險道狹路可擊，陳數移動可擊，將離士卒可擊，心怖可擊。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-4_s-4","passageId":"wu-zi_ch-2_p-4","order":4,"canonicalText":"凡若此者，選銳衝之，分兵繼之，急擊勿疑。","chunks":[["凡若此者，選銳衝之，分兵繼之，急擊勿疑。","zh-Hant"]]},{"id":"wu-zi_ch-2_p-4_s-5","passageId":"wu-zi_ch-2_p-4","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-3_p-1_s-1","passageId":"wu-zi_ch-3_p-1","order":1,"canonicalText":"武侯問曰：「進兵之道何先？","chunks":[["武侯問曰：「進兵之道何先？","zh-Hant"]]},{"id":"wu-zi_ch-3_p-1_s-2","passageId":"wu-zi_ch-3_p-1","order":2,"canonicalText":"」起對曰：「先明四輕、二重、一信。","chunks":[["」起對曰：「先明四輕、二重、一信。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-1_s-3","passageId":"wu-zi_ch-3_p-1","order":3,"canonicalText":"」曰：「何謂也？","chunks":[["」曰：「何謂也？","zh-Hant"]]},{"id":"wu-zi_ch-3_p-1_s-4","passageId":"wu-zi_ch-3_p-1","order":4,"canonicalText":"」對曰：「使地輕馬，馬輕車，車輕人，人輕戰。","chunks":[["」對曰：「使地輕馬，馬輕車，車輕人，人輕戰。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-1_s-5","passageId":"wu-zi_ch-3_p-1","order":5,"canonicalText":"明知陰陽，則地輕馬。","chunks":[["明知陰陽，則地輕馬。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-1_s-6","passageId":"wu-zi_ch-3_p-1","order":6,"canonicalText":"芻秣以時，則馬輕車。","chunks":[["芻秣以時，則馬輕車。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-1_s-7","passageId":"wu-zi_ch-3_p-1","order":7,"canonicalText":"膏鐧有餘，則車輕人。","chunks":[["膏鐧有餘，則車輕人。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-1_s-8","passageId":"wu-zi_ch-3_p-1","order":8,"canonicalText":"鋒銳甲堅，則人輕戰。","chunks":[["鋒銳甲堅，則人輕戰。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-1_s-9","passageId":"wu-zi_ch-3_p-1","order":9,"canonicalText":"進有重賞，退有重刑。","chunks":[["進有重賞，退有重刑。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-1_s-10","passageId":"wu-zi_ch-3_p-1","order":10,"canonicalText":"行之以信。","chunks":[["行之以信。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-1_s-11","passageId":"wu-zi_ch-3_p-1","order":11,"canonicalText":"令制遠，此勝之主也。","chunks":[["令制遠，此勝之主也。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-1_s-12","passageId":"wu-zi_ch-3_p-1","order":12,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-3_p-2_s-1","passageId":"wu-zi_ch-3_p-2","order":1,"canonicalText":"武侯問曰：「兵何以為勝？","chunks":[["武侯問曰：「兵何以為勝？","zh-Hant"]]},{"id":"wu-zi_ch-3_p-2_s-2","passageId":"wu-zi_ch-3_p-2","order":2,"canonicalText":"」起對曰：「以治為勝。","chunks":[["」起對曰：「以治為勝。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-2_s-3","passageId":"wu-zi_ch-3_p-2","order":3,"canonicalText":"」又問曰：「不在眾寡？","chunks":[["」又問曰：「不在眾寡？","zh-Hant"]]},{"id":"wu-zi_ch-3_p-2_s-4","passageId":"wu-zi_ch-3_p-2","order":4,"canonicalText":"」對曰：「若法令不明，賞罰不信，金之不止，鼓之不進，雖有百萬，何益於用。","chunks":[["」對曰：「若法令不明，賞罰不信，金之不止，鼓之不進，雖有百萬，何益於用。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-2_s-5","passageId":"wu-zi_ch-3_p-2","order":5,"canonicalText":"所謂治者，居則有禮，動則有威，進不可當，退不可追，前卻有節，左右應麾，雖絕成陳，雖散成行。","chunks":[["所謂治者，居則有禮，動則有威，進不可當，退不可追，前卻有節，左右應麾，雖絕成陳，雖散成行。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-2_s-6","passageId":"wu-zi_ch-3_p-2","order":6,"canonicalText":"與之安，與之危，其眾可合而不可離，可用而不可疲，投之所往，天下莫當，名曰父子之兵。","chunks":[["與之安，與之危，其眾可合而不可離，可用而不可疲，投之所往，天下莫當，名曰父子之兵。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-2_s-7","passageId":"wu-zi_ch-3_p-2","order":7,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-3_p-3_s-1","passageId":"wu-zi_ch-3_p-3","order":1,"canonicalText":"吳子曰：「凡行軍之道，無犯進止之節，無失飲食之適，無絕人馬之力。","chunks":[["吳子曰：「凡行軍之道，無犯進止之節，無失飲食之適，無絕人馬之力。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-3_s-2","passageId":"wu-zi_ch-3_p-3","order":2,"canonicalText":"此三者，所以任其上令。","chunks":[["此三者，所以任其上令。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-3_s-3","passageId":"wu-zi_ch-3_p-3","order":3,"canonicalText":"任其上令，則治之所由生也。","chunks":[["任其上令，則治之所由生也。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-3_s-4","passageId":"wu-zi_ch-3_p-3","order":4,"canonicalText":"若進止不度，飲食不適，馬疲人倦而不解舍，所以不任其上令。","chunks":[["若進止不度，飲食不適，馬疲人倦而不解舍，所以不任其上令。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-3_s-5","passageId":"wu-zi_ch-3_p-3","order":5,"canonicalText":"上令既廢，以居則亂，以戰則敗。","chunks":[["上令既廢，以居則亂，以戰則敗。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-3_s-6","passageId":"wu-zi_ch-3_p-3","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-3_p-4_s-1","passageId":"wu-zi_ch-3_p-4","order":1,"canonicalText":"吳子曰：「凡兵戰之場，立屍之地。","chunks":[["吳子曰：「凡兵戰之場，立屍之地。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-4_s-2","passageId":"wu-zi_ch-3_p-4","order":2,"canonicalText":"必死則生，幸生則死。","chunks":[["必死則生，幸生則死。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-4_s-3","passageId":"wu-zi_ch-3_p-4","order":3,"canonicalText":"其善將者，如坐漏船之中，伏燒屋之下，使智者不及謀，勇者不及怒，受敵可也。","chunks":[["其善將者，如坐漏船之中，伏燒屋之下，使智者不及謀，勇者不及怒，受敵可也。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-4_s-4","passageId":"wu-zi_ch-3_p-4","order":4,"canonicalText":"故曰：用兵之害，猶豫最大；","chunks":[["故曰：用兵之害，猶豫最大；","zh-Hant"]]},{"id":"wu-zi_ch-3_p-4_s-5","passageId":"wu-zi_ch-3_p-4","order":5,"canonicalText":"三軍之災，生於狐疑。","chunks":[["三軍之災，生於狐疑。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-4_s-6","passageId":"wu-zi_ch-3_p-4","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-3_p-5_s-1","passageId":"wu-zi_ch-3_p-5","order":1,"canonicalText":"吳子曰：「夫人當死其所不能，敗其所不便。","chunks":[["吳子曰：「夫人當死其所不能，敗其所不便。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-5_s-2","passageId":"wu-zi_ch-3_p-5","order":2,"canonicalText":"故用兵之法，教戒為先。","chunks":[["故用兵之法，教戒為先。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-5_s-3","passageId":"wu-zi_ch-3_p-5","order":3,"canonicalText":"一人學戰，教成十人。","chunks":[["一人學戰，教成十人。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-5_s-4","passageId":"wu-zi_ch-3_p-5","order":4,"canonicalText":"十人學戰，教成百人。","chunks":[["十人學戰，教成百人。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-5_s-5","passageId":"wu-zi_ch-3_p-5","order":5,"canonicalText":"百人學戰，教成千人。","chunks":[["百人學戰，教成千人。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-5_s-6","passageId":"wu-zi_ch-3_p-5","order":6,"canonicalText":"千人學戰，教成萬人。","chunks":[["千人學戰，教成萬人。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-5_s-7","passageId":"wu-zi_ch-3_p-5","order":7,"canonicalText":"萬人學戰，教成三軍。","chunks":[["萬人學戰，教成三軍。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-5_s-8","passageId":"wu-zi_ch-3_p-5","order":8,"canonicalText":"以近待遠，以佚待勞，以飽待飢。","chunks":[["以近待遠，以佚待勞，以飽待飢。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-5_s-9","passageId":"wu-zi_ch-3_p-5","order":9,"canonicalText":"圓而方之，坐而起之，行而止之，左而右之，前而後之，分而合之，結而解之。","chunks":[["圓而方之，坐而起之，行而止之，左而右之，前而後之，分而合之，結而解之。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-5_s-10","passageId":"wu-zi_ch-3_p-5","order":10,"canonicalText":"每變皆習，乃授其兵。","chunks":[["每變皆習，乃授其兵。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-5_s-11","passageId":"wu-zi_ch-3_p-5","order":11,"canonicalText":"是謂將事。","chunks":[["是謂將事。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-5_s-12","passageId":"wu-zi_ch-3_p-5","order":12,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-3_p-6_s-1","passageId":"wu-zi_ch-3_p-6","order":1,"canonicalText":"吳子曰：「教戰之令，短者持矛戟，長者持弓弩，強者持旌旗，勇者持金鼓，弱者給冢養，智者為謀主。","chunks":[["吳子曰：「教戰之令，短者持矛戟，長者持弓弩，強者持旌旗，勇者持金鼓，弱者給冢養，智者為謀主。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-6_s-2","passageId":"wu-zi_ch-3_p-6","order":2,"canonicalText":"鄉里相比，什伍相保。","chunks":[["鄉里相比，什伍相保。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-6_s-3","passageId":"wu-zi_ch-3_p-6","order":3,"canonicalText":"一鼓整兵，二鼓習陳，三鼓趨食，四鼓嚴辨，五鼓就行。","chunks":[["一鼓整兵，二鼓習陳，三鼓趨食，四鼓嚴辨，五鼓就行。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-6_s-4","passageId":"wu-zi_ch-3_p-6","order":4,"canonicalText":"聞鼓聲合，然後舉旗。","chunks":[["聞鼓聲合，然後舉旗。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-6_s-5","passageId":"wu-zi_ch-3_p-6","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-3_p-7_s-1","passageId":"wu-zi_ch-3_p-7","order":1,"canonicalText":"武侯問曰：「三軍進止。","chunks":[["武侯問曰：「三軍進止。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-7_s-2","passageId":"wu-zi_ch-3_p-7","order":2,"canonicalText":"豈有道乎？","chunks":[["豈有道乎？","zh-Hant"]]},{"id":"wu-zi_ch-3_p-7_s-3","passageId":"wu-zi_ch-3_p-7","order":3,"canonicalText":"」起對曰：「無當天竈，無當龍頭。","chunks":[["」起對曰：「無當天竈，無當龍頭。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-7_s-4","passageId":"wu-zi_ch-3_p-7","order":4,"canonicalText":"天竈者，大谷之口。","chunks":[["天竈者，大谷之口。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-7_s-5","passageId":"wu-zi_ch-3_p-7","order":5,"canonicalText":"龍頭者，大山之端。","chunks":[["龍頭者，大山之端。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-7_s-6","passageId":"wu-zi_ch-3_p-7","order":6,"canonicalText":"必左青龍，右白虎，前朱雀，後玄武，招搖在上，從事於下。","chunks":[["必左青龍，右白虎，前朱雀，後玄武，招搖在上，從事於下。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-7_s-7","passageId":"wu-zi_ch-3_p-7","order":7,"canonicalText":"將戰之時，審候風所從來。","chunks":[["將戰之時，審候風所從來。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-7_s-8","passageId":"wu-zi_ch-3_p-7","order":8,"canonicalText":"風順致呼而從之，風逆堅陳以待之。","chunks":[["風順致呼而從之，風逆堅陳以待之。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-7_s-9","passageId":"wu-zi_ch-3_p-7","order":9,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-3_p-8_s-1","passageId":"wu-zi_ch-3_p-8","order":1,"canonicalText":"武侯問曰：「凡畜卒騎，豈有方乎？","chunks":[["武侯問曰：「凡畜卒騎，豈有方乎？","zh-Hant"]]},{"id":"wu-zi_ch-3_p-8_s-2","passageId":"wu-zi_ch-3_p-8","order":2,"canonicalText":"」起對曰：「夫馬必安其處所，適其水草，節其飢飽。","chunks":[["」起對曰：「夫馬必安其處所，適其水草，節其飢飽。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-8_s-3","passageId":"wu-zi_ch-3_p-8","order":3,"canonicalText":"冬則溫燒，夏則涼廡。","chunks":[["冬則溫燒，夏則涼廡。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-8_s-4","passageId":"wu-zi_ch-3_p-8","order":4,"canonicalText":"刻剔毛鬣，謹落四下。","chunks":[["刻剔毛鬣，謹落四下。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-8_s-5","passageId":"wu-zi_ch-3_p-8","order":5,"canonicalText":"戢其耳目，無令驚駭。","chunks":[["戢其耳目，無令驚駭。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-8_s-6","passageId":"wu-zi_ch-3_p-8","order":6,"canonicalText":"習其馳逐，閑其進止。","chunks":[["習其馳逐，閑其進止。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-8_s-7","passageId":"wu-zi_ch-3_p-8","order":7,"canonicalText":"人馬相親，然後可使。","chunks":[["人馬相親，然後可使。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-8_s-8","passageId":"wu-zi_ch-3_p-8","order":8,"canonicalText":"車騎之具，鞍、勒、銜、轡，必令完堅。","chunks":[["車騎之具，鞍、勒、銜、轡，必令完堅。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-8_s-9","passageId":"wu-zi_ch-3_p-8","order":9,"canonicalText":"凡馬不傷於末，必傷於始；","chunks":[["凡馬不傷於末，必傷於始；","zh-Hant"]]},{"id":"wu-zi_ch-3_p-8_s-10","passageId":"wu-zi_ch-3_p-8","order":10,"canonicalText":"不傷於飢，必傷於飽。","chunks":[["不傷於飢，必傷於飽。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-8_s-11","passageId":"wu-zi_ch-3_p-8","order":11,"canonicalText":"日暮道遠，必數上下。","chunks":[["日暮道遠，必數上下。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-8_s-12","passageId":"wu-zi_ch-3_p-8","order":12,"canonicalText":"寧勞於人，慎無勞馬。","chunks":[["寧勞於人，慎無勞馬。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-8_s-13","passageId":"wu-zi_ch-3_p-8","order":13,"canonicalText":"常令有餘，備敵覆我。","chunks":[["常令有餘，備敵覆我。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-8_s-14","passageId":"wu-zi_ch-3_p-8","order":14,"canonicalText":"能明此者，橫行天下。","chunks":[["能明此者，橫行天下。","zh-Hant"]]},{"id":"wu-zi_ch-3_p-8_s-15","passageId":"wu-zi_ch-3_p-8","order":15,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-4_p-1_s-1","passageId":"wu-zi_ch-4_p-1","order":1,"canonicalText":"吳子曰：「夫總文武者，軍之將也。","chunks":[["吳子曰：「夫總文武者，軍之將也。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-1_s-2","passageId":"wu-zi_ch-4_p-1","order":2,"canonicalText":"兼剛柔者，兵之事也。","chunks":[["兼剛柔者，兵之事也。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-1_s-3","passageId":"wu-zi_ch-4_p-1","order":3,"canonicalText":"凡人論將，常觀於勇。","chunks":[["凡人論將，常觀於勇。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-1_s-4","passageId":"wu-zi_ch-4_p-1","order":4,"canonicalText":"勇之於將，乃數分之一爾。","chunks":[["勇之於將，乃數分之一爾。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-1_s-5","passageId":"wu-zi_ch-4_p-1","order":5,"canonicalText":"夫勇者必輕合，輕合而不知利，未可也。","chunks":[["夫勇者必輕合，輕合而不知利，未可也。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-1_s-6","passageId":"wu-zi_ch-4_p-1","order":6,"canonicalText":"故將之所慎者五：一曰理，二曰備，三曰果，四曰戒，五曰約。","chunks":[["故將之所慎者五：一曰理，二曰備，三曰果，四曰戒，五曰約。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-1_s-7","passageId":"wu-zi_ch-4_p-1","order":7,"canonicalText":"理者，治眾如治寡。","chunks":[["理者，治眾如治寡。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-1_s-8","passageId":"wu-zi_ch-4_p-1","order":8,"canonicalText":"備者，出門如見敵。","chunks":[["備者，出門如見敵。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-1_s-9","passageId":"wu-zi_ch-4_p-1","order":9,"canonicalText":"果者，臨敵不懷生。","chunks":[["果者，臨敵不懷生。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-1_s-10","passageId":"wu-zi_ch-4_p-1","order":10,"canonicalText":"戒者，雖克如始戰。","chunks":[["戒者，雖克如始戰。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-1_s-11","passageId":"wu-zi_ch-4_p-1","order":11,"canonicalText":"約者，法令省而不煩。","chunks":[["約者，法令省而不煩。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-1_s-12","passageId":"wu-zi_ch-4_p-1","order":12,"canonicalText":"受命而不辭，敵破而後言返，將之禮也。","chunks":[["受命而不辭，敵破而後言返，將之禮也。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-1_s-13","passageId":"wu-zi_ch-4_p-1","order":13,"canonicalText":"故師出之日，有死之榮，無生之辱。","chunks":[["故師出之日，有死之榮，無生之辱。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-1_s-14","passageId":"wu-zi_ch-4_p-1","order":14,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-4_p-2_s-1","passageId":"wu-zi_ch-4_p-2","order":1,"canonicalText":"吳子曰：「凡兵有四機：一曰氣機，二曰地機，三曰事機，四曰力機。","chunks":[["吳子曰：「凡兵有四機：一曰氣機，二曰地機，三曰事機，四曰力機。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-2_s-2","passageId":"wu-zi_ch-4_p-2","order":2,"canonicalText":"三軍之眾，百萬之師，張設輕重，在於一人，是謂氣機。","chunks":[["三軍之眾，百萬之師，張設輕重，在於一人，是謂氣機。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-2_s-3","passageId":"wu-zi_ch-4_p-2","order":3,"canonicalText":"路狹道險，名山大塞，十夫所守，千夫不過，是謂地機。","chunks":[["路狹道險，名山大塞，十夫所守，千夫不過，是謂地機。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-2_s-4","passageId":"wu-zi_ch-4_p-2","order":4,"canonicalText":"善行間諜，輕兵往來，分散其眾，使其君臣相怨，上下相咎，是謂事機。","chunks":[["善行間諜，輕兵往來，分散其眾，使其君臣相怨，上下相咎，是謂事機。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-2_s-5","passageId":"wu-zi_ch-4_p-2","order":5,"canonicalText":"車堅管轄，舟利櫓楫，士習戰陳，馬閑馳逐，是謂力機。","chunks":[["車堅管轄，舟利櫓楫，士習戰陳，馬閑馳逐，是謂力機。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-2_s-6","passageId":"wu-zi_ch-4_p-2","order":6,"canonicalText":"知此四者，乃可為將。","chunks":[["知此四者，乃可為將。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-2_s-7","passageId":"wu-zi_ch-4_p-2","order":7,"canonicalText":"然其威、德、仁、勇，必足以率下安眾，怖敵決疑。","chunks":[["然其威、德、仁、勇，必足以率下安眾，怖敵決疑。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-2_s-8","passageId":"wu-zi_ch-4_p-2","order":8,"canonicalText":"施令而下不犯，所在寇不敢敵。","chunks":[["施令而下不犯，所在寇不敢敵。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-2_s-9","passageId":"wu-zi_ch-4_p-2","order":9,"canonicalText":"得之國強，去之國亡。","chunks":[["得之國強，去之國亡。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-2_s-10","passageId":"wu-zi_ch-4_p-2","order":10,"canonicalText":"是謂良將。","chunks":[["是謂良將。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-2_s-11","passageId":"wu-zi_ch-4_p-2","order":11,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-4_p-3_s-1","passageId":"wu-zi_ch-4_p-3","order":1,"canonicalText":"吳子曰：「夫鼙鼓金鐸，所以威耳。","chunks":[["吳子曰：「夫鼙鼓金鐸，所以威耳。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-3_s-2","passageId":"wu-zi_ch-4_p-3","order":2,"canonicalText":"旌旗麾幟，所以威目。","chunks":[["旌旗麾幟，所以威目。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-3_s-3","passageId":"wu-zi_ch-4_p-3","order":3,"canonicalText":"禁令刑罰，所以威心。","chunks":[["禁令刑罰，所以威心。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-3_s-4","passageId":"wu-zi_ch-4_p-3","order":4,"canonicalText":"耳威於聲，不可不清。","chunks":[["耳威於聲，不可不清。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-3_s-5","passageId":"wu-zi_ch-4_p-3","order":5,"canonicalText":"目威於色，不可不明。","chunks":[["目威於色，不可不明。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-3_s-6","passageId":"wu-zi_ch-4_p-3","order":6,"canonicalText":"心威於刑，不可不嚴。","chunks":[["心威於刑，不可不嚴。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-3_s-7","passageId":"wu-zi_ch-4_p-3","order":7,"canonicalText":"三者不立，雖有其國，必敗於敵。","chunks":[["三者不立，雖有其國，必敗於敵。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-3_s-8","passageId":"wu-zi_ch-4_p-3","order":8,"canonicalText":"故曰：將之所麾，莫不從移；","chunks":[["故曰：將之所麾，莫不從移；","zh-Hant"]]},{"id":"wu-zi_ch-4_p-3_s-9","passageId":"wu-zi_ch-4_p-3","order":9,"canonicalText":"將之所指，莫不前死。","chunks":[["將之所指，莫不前死。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-3_s-10","passageId":"wu-zi_ch-4_p-3","order":10,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-4_p-4_s-1","passageId":"wu-zi_ch-4_p-4","order":1,"canonicalText":"吳子曰：「凡戰之要，必先占其將而察其才。","chunks":[["吳子曰：「凡戰之要，必先占其將而察其才。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-4_s-2","passageId":"wu-zi_ch-4_p-4","order":2,"canonicalText":"因形用權，則不勞而功舉。","chunks":[["因形用權，則不勞而功舉。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-4_s-3","passageId":"wu-zi_ch-4_p-4","order":3,"canonicalText":"其將愚而信人，可詐而誘；","chunks":[["其將愚而信人，可詐而誘；","zh-Hant"]]},{"id":"wu-zi_ch-4_p-4_s-4","passageId":"wu-zi_ch-4_p-4","order":4,"canonicalText":"貪而忽名，可貨而賂；","chunks":[["貪而忽名，可貨而賂；","zh-Hant"]]},{"id":"wu-zi_ch-4_p-4_s-5","passageId":"wu-zi_ch-4_p-4","order":5,"canonicalText":"輕變無謀，可勞而困。","chunks":[["輕變無謀，可勞而困。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-4_s-6","passageId":"wu-zi_ch-4_p-4","order":6,"canonicalText":"上富而驕，下貧而怨，可離而間。","chunks":[["上富而驕，下貧而怨，可離而間。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-4_s-7","passageId":"wu-zi_ch-4_p-4","order":7,"canonicalText":"進退多疑，其眾無依，可震而走。","chunks":[["進退多疑，其眾無依，可震而走。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-4_s-8","passageId":"wu-zi_ch-4_p-4","order":8,"canonicalText":"士輕其將而有歸志，塞易開險，可邀而取。","chunks":[["士輕其將而有歸志，塞易開險，可邀而取。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-4_s-9","passageId":"wu-zi_ch-4_p-4","order":9,"canonicalText":"進道易，退道難，可來而前。","chunks":[["進道易，退道難，可來而前。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-4_s-10","passageId":"wu-zi_ch-4_p-4","order":10,"canonicalText":"進道險，退道易，可薄而擊。","chunks":[["進道險，退道易，可薄而擊。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-4_s-11","passageId":"wu-zi_ch-4_p-4","order":11,"canonicalText":"居軍下濕，水無所通，霖雨數至，可灌而沈。","chunks":[["居軍下濕，水無所通，霖雨數至，可灌而沈。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-4_s-12","passageId":"wu-zi_ch-4_p-4","order":12,"canonicalText":"居軍荒澤，草楚幽穢，風飆數至，可焚而滅。","chunks":[["居軍荒澤，草楚幽穢，風飆數至，可焚而滅。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-4_s-13","passageId":"wu-zi_ch-4_p-4","order":13,"canonicalText":"停久不移，將士懈怠，其軍不備，可潛而襲。","chunks":[["停久不移，將士懈怠，其軍不備，可潛而襲。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-4_s-14","passageId":"wu-zi_ch-4_p-4","order":14,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-4_p-5_s-1","passageId":"wu-zi_ch-4_p-5","order":1,"canonicalText":"武侯問曰：「兩軍相望，不知其將，我欲相之，其術如何？","chunks":[["武侯問曰：「兩軍相望，不知其將，我欲相之，其術如何？","zh-Hant"]]},{"id":"wu-zi_ch-4_p-5_s-2","passageId":"wu-zi_ch-4_p-5","order":2,"canonicalText":"」起對曰：「令賤而勇者，將輕銳以嘗之。","chunks":[["」起對曰：「令賤而勇者，將輕銳以嘗之。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-5_s-3","passageId":"wu-zi_ch-4_p-5","order":3,"canonicalText":"務於北，無務於得，觀敵之來，一坐一起，其政以理，其追北佯為不及，其見利佯為不知，如此將者，名為智將，勿與戰矣。","chunks":[["務於北，無務於得，觀敵之來，一坐一起，其政以理，其追北佯為不及，其見利佯為不知，如此將者，名為智將，勿與戰矣。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-5_s-4","passageId":"wu-zi_ch-4_p-5","order":4,"canonicalText":"若其眾讙譁，旌旗煩亂，其卒自行自止，其兵或縱或橫，其追北恐不及，見利恐不得，此為愚將，雖眾可獲。","chunks":[["若其眾讙譁，旌旗煩亂，其卒自行自止，其兵或縱或橫，其追北恐不及，見利恐不得，此為愚將，雖眾可獲。","zh-Hant"]]},{"id":"wu-zi_ch-4_p-5_s-5","passageId":"wu-zi_ch-4_p-5","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-5_p-1_s-1","passageId":"wu-zi_ch-5_p-1","order":1,"canonicalText":"武侯問曰：「車堅馬良，將勇兵強，卒遇敵人，亂而失行，則如之何？","chunks":[["武侯問曰：「車堅馬良，將勇兵強，卒遇敵人，亂而失行，則如之何？","zh-Hant"]]},{"id":"wu-zi_ch-5_p-1_s-2","passageId":"wu-zi_ch-5_p-1","order":2,"canonicalText":"」起對曰：「凡戰之法，晝以旌旗旛麾為節，夜以金鼓笳笛為節。","chunks":[["」起對曰：「凡戰之法，晝以旌旗旛麾為節，夜以金鼓笳笛為節。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-1_s-3","passageId":"wu-zi_ch-5_p-1","order":3,"canonicalText":"麾左而左，麾右而右。","chunks":[["麾左而左，麾右而右。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-1_s-4","passageId":"wu-zi_ch-5_p-1","order":4,"canonicalText":"鼓之則進，金之則止。","chunks":[["鼓之則進，金之則止。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-1_s-5","passageId":"wu-zi_ch-5_p-1","order":5,"canonicalText":"二吹而行，再吹而聚，不從令者誅。","chunks":[["二吹而行，再吹而聚，不從令者誅。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-1_s-6","passageId":"wu-zi_ch-5_p-1","order":6,"canonicalText":"三軍服威，士卒用命，則戰無彊敵，攻無堅陳矣。","chunks":[["三軍服威，士卒用命，則戰無彊敵，攻無堅陳矣。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-1_s-7","passageId":"wu-zi_ch-5_p-1","order":7,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-5_p-2_s-1","passageId":"wu-zi_ch-5_p-2","order":1,"canonicalText":"武侯問曰：「若敵眾我寡，為之柰何？","chunks":[["武侯問曰：「若敵眾我寡，為之柰何？","zh-Hant"]]},{"id":"wu-zi_ch-5_p-2_s-2","passageId":"wu-zi_ch-5_p-2","order":2,"canonicalText":"」起對曰：「避之於易，邀之於阨。","chunks":[["」起對曰：「避之於易，邀之於阨。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-2_s-3","passageId":"wu-zi_ch-5_p-2","order":3,"canonicalText":"故曰：以一擊十，莫善於阨；","chunks":[["故曰：以一擊十，莫善於阨；","zh-Hant"]]},{"id":"wu-zi_ch-5_p-2_s-4","passageId":"wu-zi_ch-5_p-2","order":4,"canonicalText":"以十擊百，莫善於險；","chunks":[["以十擊百，莫善於險；","zh-Hant"]]},{"id":"wu-zi_ch-5_p-2_s-5","passageId":"wu-zi_ch-5_p-2","order":5,"canonicalText":"以千擊萬，莫善於阻。","chunks":[["以千擊萬，莫善於阻。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-2_s-6","passageId":"wu-zi_ch-5_p-2","order":6,"canonicalText":"今有少年卒起，擊金鳴鼓於阨路，雖有大眾，莫不驚動。","chunks":[["今有少年卒起，擊金鳴鼓於阨路，雖有大眾，莫不驚動。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-2_s-7","passageId":"wu-zi_ch-5_p-2","order":7,"canonicalText":"故曰：用眾者務易，用少者務隘。","chunks":[["故曰：用眾者務易，用少者務隘。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-2_s-8","passageId":"wu-zi_ch-5_p-2","order":8,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-5_p-3_s-1","passageId":"wu-zi_ch-5_p-3","order":1,"canonicalText":"武侯問曰：「有師甚眾，既武且勇；","chunks":[["武侯問曰：「有師甚眾，既武且勇；","zh-Hant"]]},{"id":"wu-zi_ch-5_p-3_s-2","passageId":"wu-zi_ch-5_p-3","order":2,"canonicalText":"背大險阻，右山左水；","chunks":[["背大險阻，右山左水；","zh-Hant"]]},{"id":"wu-zi_ch-5_p-3_s-3","passageId":"wu-zi_ch-5_p-3","order":3,"canonicalText":"深溝高壘，守以彊弩；","chunks":[["深溝高壘，守以彊弩；","zh-Hant"]]},{"id":"wu-zi_ch-5_p-3_s-4","passageId":"wu-zi_ch-5_p-3","order":4,"canonicalText":"退如山移，進如風雨，糧食又多。","chunks":[["退如山移，進如風雨，糧食又多。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-3_s-5","passageId":"wu-zi_ch-5_p-3","order":5,"canonicalText":"難與長守。","chunks":[["難與長守。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-3_s-6","passageId":"wu-zi_ch-5_p-3","order":6,"canonicalText":"」對曰：「大哉問乎！","chunks":[["」對曰：「大哉問乎！","zh-Hant"]]},{"id":"wu-zi_ch-5_p-3_s-7","passageId":"wu-zi_ch-5_p-3","order":7,"canonicalText":"非此車騎之力，聖人之謀也。","chunks":[["非此車騎之力，聖人之謀也。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-3_s-8","passageId":"wu-zi_ch-5_p-3","order":8,"canonicalText":"能備千乘萬騎，兼之徒步，分為五軍，各軍一衢。","chunks":[["能備千乘萬騎，兼之徒步，分為五軍，各軍一衢。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-3_s-9","passageId":"wu-zi_ch-5_p-3","order":9,"canonicalText":"夫五軍五衢，敵人必惑，莫之所加。","chunks":[["夫五軍五衢，敵人必惑，莫之所加。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-3_s-10","passageId":"wu-zi_ch-5_p-3","order":10,"canonicalText":"敵人若堅守以固其兵，急行間諜以觀其慮。","chunks":[["敵人若堅守以固其兵，急行間諜以觀其慮。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-3_s-11","passageId":"wu-zi_ch-5_p-3","order":11,"canonicalText":"彼聽吾說，解之而去。","chunks":[["彼聽吾說，解之而去。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-3_s-12","passageId":"wu-zi_ch-5_p-3","order":12,"canonicalText":"不聽吾說，斬使焚書，分為五戰。","chunks":[["不聽吾說，斬使焚書，分為五戰。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-3_s-13","passageId":"wu-zi_ch-5_p-3","order":13,"canonicalText":"戰勝勿追，不勝疾歸。","chunks":[["戰勝勿追，不勝疾歸。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-3_s-14","passageId":"wu-zi_ch-5_p-3","order":14,"canonicalText":"如是佯北，安行疾鬭，一結其前，一絕其後。","chunks":[["如是佯北，安行疾鬭，一結其前，一絕其後。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-3_s-15","passageId":"wu-zi_ch-5_p-3","order":15,"canonicalText":"兩軍𠾑枚，或左或右，而襲其處。","chunks":[["兩軍𠾑枚，或左或右，而襲其處。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-3_s-16","passageId":"wu-zi_ch-5_p-3","order":16,"canonicalText":"五軍交至，必有其力。","chunks":[["五軍交至，必有其力。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-3_s-17","passageId":"wu-zi_ch-5_p-3","order":17,"canonicalText":"此擊彊之道也。","chunks":[["此擊彊之道也。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-3_s-18","passageId":"wu-zi_ch-5_p-3","order":18,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-5_p-4_s-1","passageId":"wu-zi_ch-5_p-4","order":1,"canonicalText":"武侯問曰：「敵近而薄我，欲去無路，我眾甚懼，為之柰何？","chunks":[["武侯問曰：「敵近而薄我，欲去無路，我眾甚懼，為之柰何？","zh-Hant"]]},{"id":"wu-zi_ch-5_p-4_s-2","passageId":"wu-zi_ch-5_p-4","order":2,"canonicalText":"」對曰：「為此之術，若我眾彼寡，各分而乘之。","chunks":[["」對曰：「為此之術，若我眾彼寡，各分而乘之。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-4_s-3","passageId":"wu-zi_ch-5_p-4","order":3,"canonicalText":"彼眾我寡，以方從之。","chunks":[["彼眾我寡，以方從之。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-4_s-4","passageId":"wu-zi_ch-5_p-4","order":4,"canonicalText":"從之無息，雖眾可服。","chunks":[["從之無息，雖眾可服。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-4_s-5","passageId":"wu-zi_ch-5_p-4","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-5_p-5_s-1","passageId":"wu-zi_ch-5_p-5","order":1,"canonicalText":"武侯問曰：「若遇敵於谿谷之間，傍多險阻，彼眾我寡，為之奈何？","chunks":[["武侯問曰：「若遇敵於谿谷之間，傍多險阻，彼眾我寡，為之奈何？","zh-Hant"]]},{"id":"wu-zi_ch-5_p-5_s-2","passageId":"wu-zi_ch-5_p-5","order":2,"canonicalText":"」起對曰：「諸丘陵、林谷、深山、大澤，疾行亟去，勿得從容。","chunks":[["」起對曰：「諸丘陵、林谷、深山、大澤，疾行亟去，勿得從容。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-5_s-3","passageId":"wu-zi_ch-5_p-5","order":3,"canonicalText":"若高山深谷，卒然相遇，必先鼓譟而乘之。","chunks":[["若高山深谷，卒然相遇，必先鼓譟而乘之。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-5_s-4","passageId":"wu-zi_ch-5_p-5","order":4,"canonicalText":"進弓與弩，且射且虜。","chunks":[["進弓與弩，且射且虜。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-5_s-5","passageId":"wu-zi_ch-5_p-5","order":5,"canonicalText":"審察其政，亂則擊之勿疑。","chunks":[["審察其政，亂則擊之勿疑。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-5_s-6","passageId":"wu-zi_ch-5_p-5","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-5_p-6_s-1","passageId":"wu-zi_ch-5_p-6","order":1,"canonicalText":"武侯問曰：「左右高山，地甚狹迫，卒遇敵人，擊之不敢，去之不得，為之奈何？","chunks":[["武侯問曰：「左右高山，地甚狹迫，卒遇敵人，擊之不敢，去之不得，為之奈何？","zh-Hant"]]},{"id":"wu-zi_ch-5_p-6_s-2","passageId":"wu-zi_ch-5_p-6","order":2,"canonicalText":"」起對曰：「此謂谷戰，雖眾不用。","chunks":[["」起對曰：「此謂谷戰，雖眾不用。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-6_s-3","passageId":"wu-zi_ch-5_p-6","order":3,"canonicalText":"募吾材士與敵相當，輕足利兵以為前行，分車列騎隱於四旁，相去數里，無見其兵，敵必堅陳，進退不敢。","chunks":[["募吾材士與敵相當，輕足利兵以為前行，分車列騎隱於四旁，相去數里，無見其兵，敵必堅陳，進退不敢。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-6_s-4","passageId":"wu-zi_ch-5_p-6","order":4,"canonicalText":"於是出旌列旆，行出山外營之，敵人必懼。","chunks":[["於是出旌列旆，行出山外營之，敵人必懼。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-6_s-5","passageId":"wu-zi_ch-5_p-6","order":5,"canonicalText":"車騎挑之，勿令得休。","chunks":[["車騎挑之，勿令得休。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-6_s-6","passageId":"wu-zi_ch-5_p-6","order":6,"canonicalText":"此谷戰之法也。","chunks":[["此谷戰之法也。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-6_s-7","passageId":"wu-zi_ch-5_p-6","order":7,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-5_p-7_s-1","passageId":"wu-zi_ch-5_p-7","order":1,"canonicalText":"武侯問曰：「吾與敵相遇大水之澤，傾輪沒轅，水薄車騎，舟楫不設，進退不得，為之奈何？","chunks":[["武侯問曰：「吾與敵相遇大水之澤，傾輪沒轅，水薄車騎，舟楫不設，進退不得，為之奈何？","zh-Hant"]]},{"id":"wu-zi_ch-5_p-7_s-2","passageId":"wu-zi_ch-5_p-7","order":2,"canonicalText":"」起對曰：「此謂水戰，無用車騎，且留其傍。","chunks":[["」起對曰：「此謂水戰，無用車騎，且留其傍。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-7_s-3","passageId":"wu-zi_ch-5_p-7","order":3,"canonicalText":"登高四望，必得水情。","chunks":[["登高四望，必得水情。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-7_s-4","passageId":"wu-zi_ch-5_p-7","order":4,"canonicalText":"知其廣狹，盡其淺深，乃可為奇以勝之。","chunks":[["知其廣狹，盡其淺深，乃可為奇以勝之。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-7_s-5","passageId":"wu-zi_ch-5_p-7","order":5,"canonicalText":"敵若絕水，半渡而薄之。","chunks":[["敵若絕水，半渡而薄之。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-7_s-6","passageId":"wu-zi_ch-5_p-7","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-5_p-8_s-1","passageId":"wu-zi_ch-5_p-8","order":1,"canonicalText":"武侯問曰：「天久連雨，馬陷車止，四面受敵，三軍驚駭，為之奈何？","chunks":[["武侯問曰：「天久連雨，馬陷車止，四面受敵，三軍驚駭，為之奈何？","zh-Hant"]]},{"id":"wu-zi_ch-5_p-8_s-2","passageId":"wu-zi_ch-5_p-8","order":2,"canonicalText":"」起對曰：「凡用車者，陰濕則停，陽燥則起；","chunks":[["」起對曰：「凡用車者，陰濕則停，陽燥則起；","zh-Hant"]]},{"id":"wu-zi_ch-5_p-8_s-3","passageId":"wu-zi_ch-5_p-8","order":3,"canonicalText":"貴高賤下，馳其強車；","chunks":[["貴高賤下，馳其強車；","zh-Hant"]]},{"id":"wu-zi_ch-5_p-8_s-4","passageId":"wu-zi_ch-5_p-8","order":4,"canonicalText":"若進若止，必從其道。","chunks":[["若進若止，必從其道。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-8_s-5","passageId":"wu-zi_ch-5_p-8","order":5,"canonicalText":"敵人若起，必逐其跡。","chunks":[["敵人若起，必逐其跡。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-8_s-6","passageId":"wu-zi_ch-5_p-8","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-5_p-9_s-1","passageId":"wu-zi_ch-5_p-9","order":1,"canonicalText":"武侯問曰：「暴寇卒來，掠吾田野，取吾牛羊，則如之何？","chunks":[["武侯問曰：「暴寇卒來，掠吾田野，取吾牛羊，則如之何？","zh-Hant"]]},{"id":"wu-zi_ch-5_p-9_s-2","passageId":"wu-zi_ch-5_p-9","order":2,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-5_p-10_s-1","passageId":"wu-zi_ch-5_p-10","order":1,"canonicalText":"起對曰：「暴寇之來，必慮其強，善守勿應。","chunks":[["起對曰：「暴寇之來，必慮其強，善守勿應。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-10_s-2","passageId":"wu-zi_ch-5_p-10","order":2,"canonicalText":"彼將暮去，其裝必重，其心必恐，還退務速，必有不屬。","chunks":[["彼將暮去，其裝必重，其心必恐，還退務速，必有不屬。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-10_s-3","passageId":"wu-zi_ch-5_p-10","order":3,"canonicalText":"追而擊之，其兵可覆。","chunks":[["追而擊之，其兵可覆。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-10_s-4","passageId":"wu-zi_ch-5_p-10","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-5_p-11_s-1","passageId":"wu-zi_ch-5_p-11","order":1,"canonicalText":"吳子曰：「凡攻敵圍城之道，城邑既破，各入其宮。","chunks":[["吳子曰：「凡攻敵圍城之道，城邑既破，各入其宮。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-11_s-2","passageId":"wu-zi_ch-5_p-11","order":2,"canonicalText":"御其祿秩，收其器物。","chunks":[["御其祿秩，收其器物。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-11_s-3","passageId":"wu-zi_ch-5_p-11","order":3,"canonicalText":"軍之所至，無刊其木、發其屋、取其粟、殺其六畜、燔其積聚，示民無殘心。","chunks":[["軍之所至，無刊其木、發其屋、取其粟、殺其六畜、燔其積聚，示民無殘心。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-11_s-4","passageId":"wu-zi_ch-5_p-11","order":4,"canonicalText":"其有請降，許而安之。","chunks":[["其有請降，許而安之。","zh-Hant"]]},{"id":"wu-zi_ch-5_p-11_s-5","passageId":"wu-zi_ch-5_p-11","order":5,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-6_p-1_s-1","passageId":"wu-zi_ch-6_p-1","order":1,"canonicalText":"武侯問曰：「嚴刑明賞，足以勝乎？","chunks":[["武侯問曰：「嚴刑明賞，足以勝乎？","zh-Hant"]]},{"id":"wu-zi_ch-6_p-1_s-2","passageId":"wu-zi_ch-6_p-1","order":2,"canonicalText":"」起對曰：「嚴明之事，臣不能悉。","chunks":[["」起對曰：「嚴明之事，臣不能悉。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-1_s-3","passageId":"wu-zi_ch-6_p-1","order":3,"canonicalText":"雖然，非所恃也。","chunks":[["雖然，非所恃也。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-1_s-4","passageId":"wu-zi_ch-6_p-1","order":4,"canonicalText":"夫發號布令而人樂聞，興師動眾而人樂戰，交兵接刃而人樂死。","chunks":[["夫發號布令而人樂聞，興師動眾而人樂戰，交兵接刃而人樂死。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-1_s-5","passageId":"wu-zi_ch-6_p-1","order":5,"canonicalText":"此三者，人主之所恃也。","chunks":[["此三者，人主之所恃也。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-1_s-6","passageId":"wu-zi_ch-6_p-1","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-6_p-2_s-1","passageId":"wu-zi_ch-6_p-2","order":1,"canonicalText":"武侯曰：「致之奈何？","chunks":[["武侯曰：「致之奈何？","zh-Hant"]]},{"id":"wu-zi_ch-6_p-2_s-2","passageId":"wu-zi_ch-6_p-2","order":2,"canonicalText":"」對曰：「君舉有功而進饗之，無功而勵之。","chunks":[["」對曰：「君舉有功而進饗之，無功而勵之。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-2_s-3","passageId":"wu-zi_ch-6_p-2","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-6_p-3_s-1","passageId":"wu-zi_ch-6_p-3","order":1,"canonicalText":"於是武侯設坐廟廷為三行饗士大夫。","chunks":[["於是武侯設坐廟廷為三行饗士大夫。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-3_s-2","passageId":"wu-zi_ch-6_p-3","order":2,"canonicalText":"上功坐前行，餚席兼重器、上牢。","chunks":[["上功坐前行，餚席兼重器、上牢。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-3_s-3","passageId":"wu-zi_ch-6_p-3","order":3,"canonicalText":"次功坐中行，餚席器差減。","chunks":[["次功坐中行，餚席器差減。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-3_s-4","passageId":"wu-zi_ch-6_p-3","order":4,"canonicalText":"無功坐後行，餚席無重器。","chunks":[["無功坐後行，餚席無重器。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-3_s-5","passageId":"wu-zi_ch-6_p-3","order":5,"canonicalText":"饗畢而出，又頒賜有功者父母妻子於廟門外，亦以功為差。","chunks":[["饗畢而出，又頒賜有功者父母妻子於廟門外，亦以功為差。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-3_s-6","passageId":"wu-zi_ch-6_p-3","order":6,"canonicalText":"有死事之家，歲被使者勞賜其父母，著不忘於心。","chunks":[["有死事之家，歲被使者勞賜其父母，著不忘於心。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-3_s-7","passageId":"wu-zi_ch-6_p-3","order":7,"canonicalText":"行之三年，秦人興師，臨於西河，魏士聞之，不待吏令，介冑而奮擊之者以萬數。","chunks":[["行之三年，秦人興師，臨於西河，魏士聞之，不待吏令，介冑而奮擊之者以萬數。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-4_s-1","passageId":"wu-zi_ch-6_p-4","order":1,"canonicalText":"武侯召吳起而謂曰：「子前日之教行矣。","chunks":[["武侯召吳起而謂曰：「子前日之教行矣。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-4_s-2","passageId":"wu-zi_ch-6_p-4","order":2,"canonicalText":"」起對曰：「臣聞人有短長，氣有盛衰。","chunks":[["」起對曰：「臣聞人有短長，氣有盛衰。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-4_s-3","passageId":"wu-zi_ch-6_p-4","order":3,"canonicalText":"君試發無功者五萬人，臣請率以當之。","chunks":[["君試發無功者五萬人，臣請率以當之。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-4_s-4","passageId":"wu-zi_ch-6_p-4","order":4,"canonicalText":"脫其不勝，取笑於諸侯，失權於天下矣。","chunks":[["脫其不勝，取笑於諸侯，失權於天下矣。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-4_s-5","passageId":"wu-zi_ch-6_p-4","order":5,"canonicalText":"今使一死賊伏於曠野，千人追之，莫不梟視狼顧。","chunks":[["今使一死賊伏於曠野，千人追之，莫不梟視狼顧。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-4_s-6","passageId":"wu-zi_ch-6_p-4","order":6,"canonicalText":"何者？","chunks":[["何者？","zh-Hant"]]},{"id":"wu-zi_ch-6_p-4_s-7","passageId":"wu-zi_ch-6_p-4","order":7,"canonicalText":"忌其暴起而害己。","chunks":[["忌其暴起而害己。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-4_s-8","passageId":"wu-zi_ch-6_p-4","order":8,"canonicalText":"是以一人投命，足懼千夫。","chunks":[["是以一人投命，足懼千夫。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-4_s-9","passageId":"wu-zi_ch-6_p-4","order":9,"canonicalText":"今臣以五萬之眾，而為一死賊，率以討之，固難敵矣。","chunks":[["今臣以五萬之眾，而為一死賊，率以討之，固難敵矣。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-4_s-10","passageId":"wu-zi_ch-6_p-4","order":10,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wu-zi_ch-6_p-5_s-1","passageId":"wu-zi_ch-6_p-5","order":1,"canonicalText":"於是武侯從之，兼車五百乘，騎三千匹，而破秦五十萬眾，此勵士之功也。","chunks":[["於是武侯從之，兼車五百乘，騎三千匹，而破秦五十萬眾，此勵士之功也。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-6_s-1","passageId":"wu-zi_ch-6_p-6","order":1,"canonicalText":"先戰一日，吳起令三軍曰：「諸吏士當從受馳。","chunks":[["先戰一日，吳起令三軍曰：「諸吏士當從受馳。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-6_s-2","passageId":"wu-zi_ch-6_p-6","order":2,"canonicalText":"車騎與徒，若車不得車，騎不得騎，徒不得徒，雖破軍皆無易。","chunks":[["車騎與徒，若車不得車，騎不得騎，徒不得徒，雖破軍皆無易。","zh-Hant"]]},{"id":"wu-zi_ch-6_p-6_s-3","passageId":"wu-zi_ch-6_p-6","order":3,"canonicalText":"」故戰之日，其令不煩而威震天下。","chunks":[["」故戰之日，其令不煩而威震天下。","zh-Hant"]]}]}') as WorkBundle
